COLLDATA("tadabburur","ur",[[349,"§المؤمنون\ndeeds\nیہ دعا مانگئے: اے ہمارے رب!ہم ایمان لائے پس تو ہمیں بخش دے اور ہم پر رحم فرما بیشک تو بہترین رحم کرنے والا ہے.\nآپ کسی شخص کو دین دار یا دعوت کا کام کرنے والے کسی فرد کا مذاق اڑاتے دیکھئے تو اسے نصیحت کیجئے او ر یہ آیت سنائیے.\nاپنے گھر والوں اور واقف کاروں کو شرکیہ اقوال واعمال سے خبردار کیجئے اور انہیں ان امور کی خطرناکی سے آگاہ کیجئے.\nguid\nنیک لوگوں کا مذاق اڑانے سے ڈرئیے.\nایمان میں صبر کا وہی مقام ہے جو جسم میں سر کا ہے.\nآپ کی زندگی اصلاًتھوڑی ہی ہے گرچہ بہ ظاہربہت لمبی کیوں نہ ہو لہذا اللہ کے راستہ میں ہر تکلیف اور مشقت برداشت کیجئے.\nrefl\nقَالُواْ رَبَّنَا غَلَبَتۡ عَلَيۡنَا شِقۡوَتُنَا\nیعنی ہمارے اوپر حجت قائم ہوچکی تھی لیکن یہ ہماری بدبختی تھی کہ اسے نہیں مانا اور نہ اس کی پیروی کی۔ (ابن کثیر: ۳؍۲۴۹)\nانسان پر بدبختی اور سختی کے غالب ہونے کی سنگینی اور اس کے خطرے کو واضح کیجئے.\nقَالُواْ رَبَّنَا غَلَبَتۡ عَلَيۡنَا شِقۡوَتُنَا وَكُنَّا قَوۡمٗا ضَآلِّينَ ١٠٦\nاس کا سب سے بہتر مفہوم یہ بتایا گیا ہے کہ: ہم پر ہماری لذتیں اور خواہشات غالب آگئیں۔لذتوں اور خواہشات کو بدبختی کہا گیا کیونکہ یہی چیزیں وہاں تک پہنچاتی ہیں۔ اور کہا گیاکہ: اس سے مراد یہ ہے کہ اپنے ساتھ حسن ِظن رکھا اور دوسروں کے ساتھ براگمان رکھا۔ (البغوی:۱۵؍۹۱)\nلذت اور خواہش ِنفس کو بدبختی کیوں کہا گیاہے؟\nإِنَّهُۥ كَانَ فَرِيقٞ مِّنۡ عِبَادِي يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ ١٠٩ فَٱتَّخَذۡتُمُوهُمۡ سِخۡرِيًّا حَتَّىٰٓ أَنسَوۡكُمۡ ذِكۡرِي وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ ١١٠\nاس سے پتہ چلا کہ کمزوروں اور مسکینوں کا مذاق اڑانے،ان پر ہنسنے،انہیں حقیراور کمتر سمجھنے نیز انہیں فضول چیزوں میں مشغول رکھنے سے بچنا چاہئے کیونکہ یہ چیز یں اللہ سے دور کرنے والی ہیں۔ (القرطبی: ۱۵؍۹۵)\nآیت کی روشنی میں کمزوروں کا مذاق اڑانے اور ان پر ہنسنے کی سنگینی اور اس کے خطرے کو واضح کیجئے.\nإِنَّهُۥ كَانَ فَرِيقٞ مِّنۡ عِبَادِي يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ ١٠٩ فَٱتَّخَذۡتُمُوهُمۡ سِخۡرِيًّا حَتَّىٰٓ أَنسَوۡكُمۡ ذِكۡرِي وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ ١١٠\n(إنه كان فريق من عبادي)کے اندر لفظ “اِنَّ” کہ جس پر زیر او ر تشدیدہے۔ سے پتہ چلتا ہے کہ انہیں جن اسباب کی وجہ سے جہنم میں ڈالا گیا وہ ان کا اس مومن جماعت کا مذاق اڑانا اور ان پر ہنسنا ہے جو یہ دعا کرتے تھے: (ربنا آمنا فاغفر لنا وارحمنا وأنت خير الراحمين)؛ چنانچہ کفار دنیا میں کمزور مومنوں کا مذاق اڑاتے تھے یہاں تک کہ وہ اللہ کے ذکر اور ایمان سے غافل ہوجاتے تھے اور اسی وجہ سے وہ جہنم میں جائیں گے۔ (شِنقیطی: ۵؍۳۶۰)\nنیک لوگوں کا مذاق اڑانے اور ان پر ہنسنے کا بڑا بھیانک انجام ہے۔وہ کیا ہے؟\nقَٰلَ كَمۡ لَبِثۡتُمۡ فِي ٱلۡأَرۡضِ عَدَدَ سِنِينَ ١١٢ قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖ فَسۡـَٔلِ ٱلۡعَآدِّينَ ١١٣\nاس کا مقصد یہ ہے کہ انہیں اس بات سے واقف کرایا جائیگا کہ دنیا میں ان کی عمریں بہت کم تھیں اور وہی ایک لمبے عذاب کا سبب بنیں۔ (ابن عطیہ: ۴؍۱۵۸)\nاللہ تعالیٰ جہنمیوں سے اس مدت کے بارے میں کیوں سوال کرے گا جو انہوں نے دنیا میں گذاری تھی؟\nأَفَحَسِبۡتُمۡ أَنَّمَا خَلَقۡنَٰكُمۡ عَبَثٗا وَأَنَّكُمۡ إِلَيۡنَا لَا تُرۡجَعُونَ ١١٥ فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِيمِ ١١٦\n(فتعالى الله) یعنی: اس باطل گمان سے جو اُس کی حکمت کے منافی ہےاللہ تعالیٰ بہت بڑا اور بلند تر ہے ۔(السعدی؍۵۶۰)\nآیت کے شروع میں لوگوں کے بے مطلب اور بے کار گمان کا ذکر کرنے کے بعد (فتعالى الله)کا جملہ کیوں لایا گیا؟\nوَمَن يَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرۡهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ ١١٧\nذرا دیکھیں!کیسے مومنوں کی کامیابی سے اس سورت کو شروع کیا اور اسے کافروں کی ناکامی پر ختم کیا تاکہ دونوں جماعتوں کے درمیان دوری کو واضح کردے۔اور اللہ ہی بہتر جانتا ہے۔(ابن جزی: ۲؍۷۹)\nاس سورت کے پہلے حصہ کی اس کے آخری حصہ سے کیا مناسبت ہے؟\nwords\nاخسَأُواذلت ميں پڑے رهو.\nفَاتَّخَذتُمُوهُم سِخرِيًّاتم ان كا مذاق اڑانے ميں لگے رهے.\nالعَآدِّينَحساب دان / جو دنوں كي گنتي كرتے هيں."],[350,"§النور\ndeeds\nفرد اور معاشرے پر زناکی خطرناکی پر مشتمل کوئی مضمون لکھئے یا پیغام بھیجئے.\nمقالہ یا مختصر کتابچہ کے ذریعہ میڈیا کے ذریعہ پھیلائے جارہے نفاق کی خطرناکی واضح کیجئے جو عورت کے حجاب کو اتاردینے،مردوں اور عورتوں کے اختلاط اور شادی کے بجائے حرام دوستی کی دعوت دے رہے ہیں.\nلوگوں کی عزت پر کیچڑ اچھالنے کے نقصانات پر درس دیجئے.\nguid\nزانی اور زانیہ کو مشرک مرد اور مشرک عورت کے ساتھ نکاح کے حکم میں ذکرکرنے کا مقصد زنا سے شدید نفرت دلانی ہے.\nکسی کی عزت پر حرف نہ رکھئے.\nاللہ تعالیٰ نے اسی لئے حدود مشروع کی ہیں تاکہ معاشرہ کی اصلاح ہو،لوگ گندے کاموں سے دور رہیں اور مظلوم کو انصاف دلایا جاسکے.\nrefl\nٱلزَّانِيَةُ وَٱلزَّانِي فَٱجۡلِدُواْ كُلَّ وَٰحِدٖ مِّنۡهُمَا مِاْئَةَ جَلۡدَةٖۖ وَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةٞ فِي دِينِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ وَلۡيَشۡهَدۡ عَذَابَهُمَا طَآئِفَةٞ مِّنَ ٱلۡمُؤۡمِنِينَ ٢\nحکم کا خیال کرنے کے لئے زانی سے پہلے زانیہ کو ذکر کیا گیا ہے کیونکہ آدمی کے زنا کرنے کا عورت ہی سبب بنتی ہے اس لئے کہ اس کی ہی مدد سے آدمی زنا کرپاتا ہے۔اگر عورت اپنے نفس کو روک لے تو آدمی زنا پر قدرت نہیں پاسکتا چنانچہ عورت کو پہلے ذکر کرنے میں اسے سختی سے ڈرانا مقصد ہے۔(ابن عاشور: ۱۸؍۱۴۶)\nزانی سے پہلے زانیہ کو کیوں ذکر کیا گیا ہے؟\nٱلزَّانِيَةُ وَٱلزَّانِي فَٱجۡلِدُواْ كُلَّ وَٰحِدٖ مِّنۡهُمَا مِاْئَةَ جَلۡدَةٖۖ وَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةٞ فِي دِينِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ وَلۡيَشۡهَدۡ عَذَابَهُمَا طَآئِفَةٞ مِّنَ ٱلۡمُؤۡمِنِينَ ٢\nحقیقت میں یہ اللہ کی طرف سے بندوں پر رحمت ہے کیوں کہ اللہ تعالیٰ نے محمد صلی اللہ علیہ وسلم کو تمام جہاں کے لئے رحمت بناکر بھیجا ہے اور اللہ سبحانہ وتعالیٰ اپنے بندوں پر کسی ماں کے اپنے بچے پر مہربان ہونے سے زیادہ بڑھ کر مہربان ہے لیکن کبھی کبھی اس طرح کی واجبی رحمت بعض افراد کے خلاف بغیر سختی اور تکلیف سے حاصل نہیں ہوپاتی۔ (ابن تیمیہ: ۴؍۴۸۶)\nاللہ تعالیٰ کی رحمت اس کے بندوں پر بسااوقات کچھ سختی اور تکلیف کے ساتھ ہوتی ہے۔آیت کریمہ کی روشنی میں اسے واضح کیجئے.\nوَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةٞ فِي دِينِ ٱللَّهِ\nیہاں جس شفقت اور نرمی سے روکا گیا ہے اس سے طبعی اور فطری نرمی مراد نہیں ہے بلکہ وہ نرمی مراد ہے جو حاکم کو حد جاری کرنے سے روک سکتی ہے۔ یہاں ایسی نرمی جائز نہیں ہے۔(ابن کثیر:۳؍۲۵۳)\nآیت میں کس نرمی سے روکا گیا ہے؟\nوَلۡيَشۡهَدۡ عَذَابَهُمَا طَآئِفَةٞ مِّنَ ٱلۡمُؤۡمِنِينَ ٢\nمومنوں کی ایک جماعت کی موجودگی میں حد جاری کرنے کی حکمت یہ ہے کہ یہ مشہور ہوجائے اور اس سے اسے رسوائی ہو نیز دوسرے مجرمین باز آجائیں۔ (السعدی؍۵۶۱)\nحد جاری کرتے وقت لوگوں کے حاضر ہونے کا کیا فائدہ ہے؟\nٱلزَّانِي لَا يَنكِحُ إِلَّا زَانِيَةً أَوۡ مُشۡرِكَةٗ وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوۡ مُشۡرِكٞۚ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلۡمُؤۡمِنِينَ ٣\nاس آیت کے اندر زنا کی رذالت اور قباحت کا بیان ہے کہ یہ فعل ِبد زانی اور اس کے ساتھ شریک ہونے والے کی عزت پر ایسا دھبہ لگادیتا ہے جو کسی دوسرے گناہ سے نہیں لگ سکتا۔ (السعدی؍۵۶۱)\nآیت کے اندر زنا کی بے انتہا قباحت کا بیان ہے۔ اس کی وضاحت کیجئے.\nوَٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ثُمَّ لَمۡ يَأۡتُواْ بِأَرۡبَعَةِ شُهَدَآءَ فَٱجۡلِدُوهُمۡ ثَمَٰنِينَ جَلۡدَةٗ وَلَا تَقۡبَلُواْ لَهُمۡ شَهَٰدَةً أَبَدٗاۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ٤\nاللہ تعالیٰ نے آیت میں عورتوں کا ذکر کیا ہے کیوں کہ ان کی اہمیت زیادہ ہے، اوران پر برائی کی تہمت لگانا زیادہ قبیح ہے اور دلوں کو زیادہ زخمی کرنے والا ہے اور مردوں پر تہمت لگانا بھی قیاس اور اجماع ِامت دونوں اعتبار سے اس آیت کے حکم میں داخل ہے۔(القرطبی: ۱۵؍۱۲۳)\nتہمت لگانے میں خاص کر عورتوں کا ہی ذکر کیوں کیا گیا جبکہ اس حکم میں مرد بھی شامل ہیں؟\nوَٱلۡخَٰمِسَةُ أَنَّ لَعۡنَتَ ٱللَّهِ عَلَيۡهِ إِن كَانَ مِنَ ٱلۡكَٰذِبِينَ ٧\nلعان میں عورت کے لئے ”غضب“کا لفظ خاص کیا گیا اس لئے کہ عموماً کوئی مرد نہیں چاہتا کہ وہ اپنی بیوی پرزناکی تہمت لگائے اور اسے بدنام کرے۔مگر صرف اسی صورت میں جب وہ سچا اور معذور ہوتا ہے۔ اور عورت بھی جانتی ہے کہ وہ اپنی تہمت میں سچا ہے۔اسی لئے پانچویں مرتبہ عورت سے کہلوایا گیاکہ اگر اس کا شوہر سچا ہو تو عورت پر اللہ کا غضب ہو۔اور غضب کے حقدار وہی ہوتے ہیں جو حق کو جان کراس سے روگردانی کرتے ہیں۔ (ابن کثیر: ۳؍۲۵۷)\nلعان میں عورت کے ساتھ غضب کو خاص کیوں کیا گیا؟\nwords\nوَفَرَضنَاهَاهم نے اس كے احكام پر عمل كو واجب كيا.\nطَائِفَةٌايك جماعت.\nيَرمُونَزنا كا الزام لگاتے هيں.\nالمُحصَنَاتِپاكدامن عورتيں اور مرد.\nوَيَدرَأُدور كرتا هے سزا كو."],[351,"§النور\ndeeds\nصحیح بخاری میں عائشہ رضی اللہ عنہا پر تہمت لگائے جانے سے متعلق حدیث پڑھئے،پھر اس سے تین فوائد نکالئے.\nافواہوں کی ترویج کو کیسے روکا جاسکتا ہے؟ تین وسائل ذکر کیجئے.\nاپنے معاشرے میں فحش کاموں کے پھیلنے سے روکنے کا حل پیش کیجئے.\nguid\nمومن کے حق میں اللہ کا ہر فیصلہ خیر ہی ہوتا ہے لہذا کسی بھی مصیبت پر غمگین نہ ہو ں، ہوسکتا ہے کہ آپ کے لئے کوئی خیر مقدر ہو.\nمومن بھائیوں اور بہنوں کے بارے میں اچھا گمان رکھئے.\nکسی پر تہمت لگانا اور بلا علم کوئی با ت کہناحرام ، گھناؤنا عمل اور عظیم جرم ہے.\nrefl\nإِنَّ ٱلَّذِينَ جَآءُو بِٱلۡإِفۡكِ عُصۡبَةٞ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرّٗا لَّكُمۖ بَلۡ هُوَ خَيۡرٞ لَّكُمۡۚ لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِي تَوَلَّىٰ كِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِيمٞ ١١\n(بل هو خير لكم)یہ خطاب مسلمانوں کے لئے ہے اوراس میں ان کے لئے بھلائی پانچ وجوہات سے ہے: ۱۔ام المومنین عائشہ صدیقہ رضی اللہ عنہا کی براءت، ۲۔ اللہ تعالیٰ کا اُن کی شان میں وحی نازل کرکے ان کی عزت واکرام کرنا،۳۔ ان کے خلاف تہمت لگائے جانے پر انہیں بہت زیادہ اجروثواب کا ملنا،۴۔ مومنوں کو نصیحت اور۵۔ تہمت لگانے والوں سے بدلہ لینا۔ (ابن جزی: ۲؍۸۴)\nواقعۂ اِفک کے اندر خیر کی بعض صورتوں کی وضاحت کیجئے.\nلَّوۡلَآ إِذۡ سَمِعۡتُمُوهُ ظَنَّ ٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بِأَنفُسِهِمۡ خَيۡرٗا وَقَالُواْ هَٰذَآ إِفۡكٞ مُّبِينٞ ١٢\nمطلب یہ ہے کہ مومن مردوں اور عورتوں کے لئے مناسب یہی تھا کہ اس سنگین مسئلہ کو اپنے اوپر ہی قیاس کرتے اگر یہ چیز ان کے لئے بعید تھی تو عائشہ صدیقہ رضی اللہ عنہا کے لئے ان کی فضیلتوں کی بناپر بدرجہ اولیٰ بعید تھی۔اس طرح کی فکر ابوایوب انصاری رضی اللہ عنہ سے مروی ہے کہ انہوں نے اپنی بیوی سے پوچھا: کیا اس طرح کی حرکت تم سے ہوسکتی ہے؟ انہوں نے جواب دیا: نہیں اللہ کی قسم، تو ابوایوب نے کہا: تو عائشہ تو تم سے زیادہ افضل ہیں!ان کی اہلیہ نے کہا:ہاں!(ابن جُزی: ۲؍۸۵)\nاس وقت ایک مسلمان کے لئے کیا واجب ہے جب وہ نیک لوگوں کے تعلق سے غیر مناسب بات سنے؟\nإِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَيۡسَ لَكُم بِهِۦ عِلۡمٞ وَتَحۡسَبُونَهُۥ هَيِّنٗا وَهُوَ عِندَ ٱللَّهِ عَظِيمٞ ١٥ وَلَوۡلَآ إِذۡ سَمِعۡتُمُوهُ قُلۡتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ عَظِيمٞ ١٦\n(تلَقَّونه) اس کا مفہوم یہ ہے کہ تم اس قبیح گفتگو کو ایک دوسرے میں پھیلا رہے تھے۔اس کلام کے اندر اور اس کے پہلے اور بعد میں ان لوگوں کے لئے عتاب اور سرزنش ہے جنہوں نے واقعۂ اِفک میں اپنے آپ کو ملوّث کیا گرچہ انہیں اس پر یقین نہیں تھا کیوں کہ ان کے لئے ضروری یہ تھا وہ اس کا بالکل ذکر نہ کرتے بلکہ پوری طرح چھوڑدیتے۔ یہی وجہ ہے کہ تین باتوں پر ان کی سرزنش کی گئی: ۱۔ انہوں نے اسے زبانی حاصل کیا یعنی دوسرے سے پوچھا اور اس سے لیا۔۲۔ اپنی زبان سے اسے بیان کیا۔۳۔ انہوں نے اسے ہلکا سمجھا جبکہ یہ اللہ کے نزدیک بہت بڑی بات تھی۔ (بألسنتكم) اور (بأفواهكم) یعنی زبان اور منہ کا ذکر کرکے اس بات کی طرف اشارہ ہے کہ وہ گفتگو صرف زبانی تھی کیوں کہ دل سے(یقینی طور پر) وہ اس کی حقیقت کو نہیں جانتے تھے۔ (ابن جزی: ۲؍۸۵)\nآیت کی روشنی میں نیک لوگوں کے تعلق سے پھیلائی گئی افواہوں کے بارے میں صحیح موقف کیا ہونا چاہئے؟اس کی وضاحت کیجئے.\nإِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَيۡسَ لَكُم بِهِۦ عِلۡمٞ وَتَحۡسَبُونَهُۥ هَيِّنٗا وَهُوَ عِندَ ٱللَّهِ عَظِيمٞ ١٥\nاس سے ایک اخلاقی ادب کا پتہ چلتا ہے کہ آدمی کو اپنی زبان سے وہی بات کہنی چاہئے جس کا اسے علم و یقین ہو۔ (ابن عاشور: ۱۸؍۱۷۸)\nآیت کریمہ کے اندر آداب گفتگو کے ایک ادب کی وضاحت کی گئی ہے۔وہ کیا ہے؟\nوَتَحۡسَبُونَهُۥ هَيِّنٗا وَهُوَ عِندَ ٱللَّهِ عَظِيمٞ ١٥\nاس آیت کریمہ میں بعض گناہوں کو معمولی اور حقیر سمجھ کر انہیں کرنے پر سخت ڈانٹ ڈپٹ اور پھٹکار ہے۔پس بندے کا گناہوں کو ہلکا شمار کرنا اسے کوئی فائدہ نہیں دیتااور نہ اس سے گناہ کی سزا میں کمی ہی کی جاتی ہے بلکہ اس طرح گناہ دگنا چوگنا ہوجاتا ہے اور گناہ میں دوبارہ مبتلا ہونا اس کے لئے آسان ہوجاتا ہے۔ (السعدی؍۵۶۴)\nبعض گناہوں کو ہلکا سمجھنے سے کیا خطرہ ہوسکتا ہے؟\nوَلَوۡلَآ إِذۡ سَمِعۡتُمُوهُ قُلۡتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ عَظِيمٞ ١٦\nعلماء کا کہنا ہے کہ ایک انسان ایمان کے جس مقام پر فائز ہوتا ہے،ایک مومن صلاح وتقویٰ کی جس خوبی کا مالک ہوتا ہے اور ایک مسلمان جس پاکیزگی کے لباس سے آراستہ ہوتا ہے اس کے مقام، تقویٰ اور پاکیزگی کو ایسی محتمل افواہوں کو پھیلاکر ختم نہیں کیا جاسکتا جو بے بنیاد اور بگاڑ پر مبنی ہوں۔ (القرطبی: ۱۵؍۱۷۲)\nنیک لوگوں کے تعلق سے بے بنیاد وفاسد افواہوں اور پروپیگنڈوں کے بارے میں ہمارا کیا موقف ہونا چاہئے؟\nإِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلۡفَٰحِشَةُ فِي ٱلَّذِينَ ءَامَنُواْ لَهُمۡ عَذَابٌ أَلِيمٞ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ١٩\nاس سے ان منافقوں کی طرف اشارہ ہے جن کی خواہش تھی کہ واقعۂ اِفک لوگوں میں مشہور ہوجائے۔اِن کے علاوہ دوسرے اُن لوگوں پر بھی اس کا اطلاق ہوگا جو اُن منافقین کے نقش ِقدم پر چلیں گے۔ (ابن جزی: ۲؍۸۵)\nاس آیت میں منافقوں کی کون سی صفت کا ذکر کیا گیا ہے؟\nwords\nبِالإِفكِانتهائي برا جھوٹ/ حضرت عائشه رضي الله عنها پر زنا كي تهمت.\nعُصبَةٌ مِنكُمتم ميں سے ايك جماعت.\nأَفَضتُم فِيهِتم بھي حديث افك ميں گفتگو كرنے لگے.\nبُهتَانٌجھوٹ.\nيَعِظُكُمُوه تمهيں منع كرتا هے."],[352,"§النور\ndeeds\nاللہ سے عاجزی اور اصرار کے ساتھ دعا مانگئے کہ وہ آپ کے نفس کا تزکیہ فرمائے.\nجو آپ کے ساتھ برائی کرے آپ اس کے ساتھ بھلائی کیجئے.\nاجازت سے متعلق آداب سیکھئے اور ا ن پر عمل کیجئے.\nguid\nرشتہ توڑنے یا نیکی نہ کرنے کی قسم نہ کھائیے۔اگر آپ نے ایسی کوئی قسم کھالی ہو تو قسم توڑکر اس کا کفارہ دے دیجئے.\nپاکدامن اور معصوم بھولی بھالی مومنہ عورتوں پر تہمت لگانا بہت بڑا گناہ ہے.\nیاد رکھئے کہ قیامت کے دن آپ کے اعضاء بات کریں گے اورآپ کے قول وعمل پر گواہی دیں گے.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ وَمَن يَتَّبِعۡ خُطُوَٰتِ ٱلشَّيۡطَٰنِ فَإِنَّهُۥ يَأۡمُرُ بِٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۚ\nاس کلام کے اندر شیطان کی پیروی اور اس کے وسوسوں پر عمل کرنے کی طرف اشارہ ہے۔گویا کہا گیا:تم شیطان کی اس طرح کی غلط چیزوں میں بالکل پیروی نہ کرو۔انہی میں بدکاری کو پسند کرنا اور اسے عام کرنا بھی شامل ہے۔ (آلوسی: ۹؍۳۲۰)\nاللہ تعالیٰ نے شیطان کے نقش ِقد م کی پیروی کرنے سے کیوں منع کیا؟بلاواسطہ اس کی پیروی کرنے سے منع نہیں کیا؟\nوَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدٗا وَلَٰكِنَّ ٱللَّهَ يُزَكِّي مَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ ٢١\nبعض مفسرین کے نزدیک آیت کے اندر عموم پایا جاتا ہے۔وہ اس کا مطلب یہ بیان کرتے ہیں کہ اللہ تعالیٰ نے خبر دی ہے کہ گناہوں سے محفوظ رکھنے میں اگر اس کا فضل اور رحمت نہ ہوتی تو تم میں سے کوئی بھی پاکباز نہ رہ سکتا تھا۔ (البغوی: ۳؍۲۸۱)\nکیا کوئی اپنے آپ کو غلطیوں سے بچاسکتا ہے؟\nوَلَا يَأۡتَلِ أُوْلُواْ ٱلۡفَضۡلِ مِنكُمۡ وَٱلسَّعَةِ أَن يُؤۡتُوٓاْ أُوْلِي ٱلۡقُرۡبَىٰ وَٱلۡمَسَٰكِينَ وَٱلۡمُهَٰجِرِينَ فِي سَبِيلِ ٱللَّهِۖ وَلۡيَعۡفُواْ وَلۡيَصۡفَحُوٓاْۗ أَلَا تُحِبُّونَ أَن يَغۡفِرَ ٱللَّهُ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٌ ٢٢\nیہ آیت کریمہ اس وقت نازل ہوئی جب ابوبکر صدیق رضی اللہ عنہ نے قسم کھالی تھی کہ مِسطح رضی اللہ عنہ پر اب خرچ نہیں کریں گے کیوں کہ انہوں نے بھی واقعۂاِفک میں حصہ لیا تھا۔ابوبکر رضی اللہ عنہ ان پر ان کی محتاجگی اور قرابت داری یعنی خالہ زاد بہن کے بیٹے ہونےکی وجہ سے خرچ کررہے تھے، چنانچہ جب یہ آیت نازل ہوئی تو ابوبکر رضی اللہ عنہ نے ان کے ساتھ حسن سلوک اور ان پر خرچ دوبارہ شروع کردیا اور اپنی قسم کا کفارہ ادا کیا۔ بعض علماء کرام کہتے ہیں کہ قرآن میں اللہ سے سب سے زیادہ امید والی یہ آیت ہے کیوں کہ اللہ تعالیٰ نے تہمت لگانے والے کے ساتھ بھی حسن ِسلوک کی وصیت کی ہے۔پھر یہ کہ آیت کا لفظ عام ہے کہ کوئی بھی نیک کام چھوڑنے کی قسم نہ کھائے(ألا تُحِبونَ أَن يَغفِرَ الله لَكُم) یعنی جس طرح تم چاہتے ہو کہ اللہ تمہیں معاف کردے اسی طرح تم بھی انہیں معاف کردو جنہوں نے تمہارے ساتھ برا سلوک کیا ہے۔ چنانچہ جب یہ آیت نازل ہوئی تو ابوبکر رضی اللہ عنہ نے کہا: بیشک مجھے پسند ہے کہ اللہ مجھے معاف فرمادے۔اس کے بعد انہوں نے دوبارہ مسطح کا خرچ جاری کردیا۔ (ابن جزی:۲؍۸۷)\nاگر کوئی آپ کے ساتھ غلط رویہ اپنائے تو کیا آپ اس کے ساتھ حسن سلوک کرنا چھوڑدیں گے؟\nوَلۡيَعۡفُواْ وَلۡيَصۡفَحُوٓاْۗ أَلَا تُحِبُّونَ أَن يَغۡفِرَ ٱللَّهُ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٌ ٢٢\nبیشک بدلہ عمل ہی کی جنس سے ہوتا ہے چنانچہ جس طرح آپ دوسروں کی غلطیوں کو معاف کریں گے اور ان کے ساتھ عفوودرگذر سے کام لیں گے تو اللہ بھی آپ کو معاف کردے گا اور عفوودرگذر سے کام لیگا۔(ابن کثیر: ۲؍۲۶۷)\nآیت کی روشنی میں اس اصول پر روشنی ڈالئے کہ بدلہ عمل کی جنس سے ہوتا ہے؟\nإِنَّ ٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ٱلۡغَٰفِلَٰتِ ٱلۡمُؤۡمِنَٰتِ لُعِنُواْ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَلَهُمۡ عَذَابٌ عَظِيمٞ ٢٣\nبدکاری سے غافل وہ عورت ہوتی ہے جس کے دل میں بدکاری کے عمل کا خیال بالکل نہ آئے اور عائشہ صدیقہ رضی اللہ عنہا ایسی ہی تھیں۔ (البغوی:۳؍۲۸۲)\nبدکاریوں اور شریعت مخالف کاموں سے غفلت کیسے ہوتی ہے؟\nيَوۡمَ تَشۡهَدُ عَلَيۡهِمۡ أَلۡسِنَتُهُمۡ وَأَيۡدِيهِمۡ وَأَرۡجُلُهُم بِمَا كَانُواْ يَعۡمَلُونَ ٢٤\nکیونکہ پاکباز عورتوں پر تہمت لگانے میں ان اعضاء کا عمل دخل ہوتاہے چنانچہ ایسے لوگ زبان سے تہمت لگاتے ہیں اور جن عورتوں پر تہمت لگاتے ہیں ان کی طرف ہاتھوں سے اشارہ کرتے ہیں نیز اپنے پیروں سے چل کر یہ خبر پہنچانے کے لئے لوگوں کی مجلسوں تک جاتے ہیں۔ (ابن عاشور: ۱۸؍۱۹۱)\nجسم کے دوسرے اعضاء کو چھوڑکر انہی اعضاء کا ذکر کیوں کیا گیا؟\nٱلۡخَبِيثَٰتُ لِلۡخَبِيثِينَ وَٱلۡخَبِيثُونَ لِلۡخَبِيثَٰتِۖ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِۚ أُوْلَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَۖ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ ٢٦\nقاضی ابوسائب رحمہ اللہ نے کہا: میں ایک دن داعی حسن بن زید کی مجلس میں بیٹھا تھا کہ مجلس میں موجود ایک شخص نے بدکاری کی تہمت کے ساتھ عائشہ رضی اللہ عنہا کا ذکر کیا۔ یہ سن کر انہوں نے کہا:اے غلام! اس کی گردن ماردو۔ اس پر علویوں نے کہا: یہ اپنے شیعوں میں سے ہے تو انہوں نے فرمایا: اللہ کی پناہ! اس شخص نے نبی صلی اللہ علیہ وسلم پر تہمت لگائی ہے کیوں کہ اللہ تعالیٰ نے فرمایا: (الخبيثات للخبيثين والخبيثون للخبيثات والطيبات للطيبين والطيبون للطيبات أولئك مبرأون مما يقولون لهم مغفرة ورزق كريم)پس اگر عائشہ رضی اللہ عنہا خبیث تھیں تو نبی صلی اللہ علیہ وسلم بھی نعوذ باللہ خبیث ہوئے حالانکہ آپ ایسے نہیں تھے۔لہذا یہ شخص کافر ٹھہرا،اس کی گردن ماردو۔قاضی ابوسائب کہتے ہیں:چنانچہ میری موجودگی میں اس کی گردن ماردی گئی۔ اسے لالکائی نے روایت کیا ہے۔ (ابن تیمیہ: ۴؍۵۰۵)\nام المومنین عائشہ رضی اللہ عنہا پر طعن وتشنیع کرنا نبی صلی اللہ علیہ وسلم پر طعن وتشنیع کرنا ہے۔ اس کی وضاحت کیجئے.\nwords\nمَا زَكَىگناهوں سے پاك نه هوا.\nوَلاَ يَأتَلِنه وه قسم اٹھائے.\nأُولُو الفَضلِدين اور مال ميں اهل فضل.\nالغَافِلاَتِوه پاكدامن عورتيں جنهيں برائي كا خيال تك نهيں آيا.\nتَستَأنِسُواگھروالوں سے اجازت حاصل كرلو."],[353,"§النور\ndeeds\nآج اللہ کی حرام کردہ چیزوں سے اپنی نظریں جھکانے کی اور زیادہ کوشش کیجئے.\nبذریعہ پیغا م اللہ کی حرام کردہ چیزوں سے نظریں جھکالینے کے فوائد بتائیے، خصوصاً نئے ایجاد کردہ آلات میں.\nآج ہی اللہ کے حضوراپنے تمام گناہوں سے توبہ کرلیجئے.\nguid\nیاد رکھئے کہ اللہ تعالیٰ آپ کے ہر ظاہر وباطن کو جانتا ہے لہذا ہوشیار رہئے کہ اللہ آپ کی کوئی ایسی بات جان لے جس سے وہ ناراض ہوجائے.\nگناہوں سے توبہ کرلینا حال اور مستقبل کی کامیابی کا ضامن ہے.\nخواتین میں مکمل حجاب کا عام ہونا معاشرے کی سعادت کے اسباب میں سے ہے.\nrefl\nوَإِن قِيلَ لَكُمُ ٱرۡجِعُواْ فَٱرۡجِعُواْۖ هُوَ أَزۡكَىٰ لَكُمۡۚ\nقتادہ رحمہ اللہ سے روایت ہے کہ مہاجرین میں سے ایک شخص نے کہا:میں نے اپنی پوری زندگی میں اس آیت پر عمل کرنا چاہالیکن کوئی موقع نہ ملا کہ اپنے کسی دوست کے گھر جانے کی صورت میں اجازت لینے پر وہ مجھ سے کہتاکہ لوٹ جاؤ اورمیں خوشی خوشی لوٹ جاتا اس آیت کی روشنی میں: (وإن قيل لكم ارجعوا فارجعوا هو أزكى لكم) یعنی:اگر تم سے کہا جائے کہ لوٹ جاؤ تو لوٹ جاؤ یہی تمہارے لئے پاکیزگی کا سبب ہے۔ (الطبری: ۱۹؍۱۵۰)\nاگر آپ کسی کے یہاں جانے کی اجازت مانگیں اور آپ سے کہا جائے کہ واپس جائیں تو آپ کو کیسا لگے گا؟\nقُل لِّلۡمُؤۡمِنِينَ يَغُضُّواْ مِنۡ أَبۡصَٰرِهِمۡ وَيَحۡفَظُواْ فُرُوجَهُمۡۚ ذَٰلِكَ أَزۡكَىٰ لَهُمۡۚ\nآنکھ دل کی طرف بہت بڑا دروازہ ہے اور محسوس چیزوں کو اس تک پہنچانے کے لئے یہ سب سے زیادہ سرگرم رہتی ہے اور اسی وجہ سے اس سے غلطیاں بھی بہت زیادہ ہوتی ہیں جس سے محتاط رہنا بہت ضروری ہے اور تمام محرمات سے آنکھ کا جھکانا واجب ہے۔نیز ہر اس چیز سے آنکھوں کا نیچی کرنا ضروری ہے جس سے فتنہ میں مبتلا ہونے کا اندیشہ ہو۔ (القرطبی: ۱۵؍۲۰۳)\nآنکھ کی اہمیت اور اس کے خطرے کی سنگینی کی وضاحت کیجئے.\nقُل لِّلۡمُؤۡمِنِينَ يَغُضُّواْ مِنۡ أَبۡصَٰرِهِمۡ وَيَحۡفَظُواْ فُرُوجَهُمۡۚ ذَٰلِكَ أَزۡكَىٰ لَهُمۡۚ\nجو اللہ کی خاطر کوئی چیز چھوڑدیتا ہے تو اللہ تعالیٰ اسے اس سے بہتر بدلہ عطاکرتا ہے اور جو کوئی اپنی آنکھوں کو حرام پر پڑنے سے بچائے رکھتا ہے اللہ تعالیٰ اس کی بصیرت کو روشن کردیتا ہے۔نیز اگر بندہ اپنی شرم گاہ اور نظر کو حرام اور اس کے مقدمات میں پڑنے سے بچاسکتا ہے باوجود یہ کہ شہوت کا داعیہ پوری طرح موجود ہو تو وہ دوسرے حرام میں پڑنے سے اپنے آپ کو زیادہ بچا سکتا ہے اسی لئے اللہ تعالیٰ نے یہاں حفاظت کا لفظ استعمال کیا ہے۔ پس اگر حفاظت کرنے والا کسی محفوظ چیز کی حفاظت و نگرانی کی کوشش نہیں کرتا نیز ان اسباب کو بروئے کارنہیں لاتا جو اس کی حفاظت کے لئے ضروری ہیں تو وہ چیز محفوظ نہیں رہ سکتی۔اسی طرح نظر اور شرم گاہ کا معاملہ ہے کہ اگر بندہ ان کی حفاظت کی کوشش نہیں کرتا ہے تو وہ اس کو آزمائشوں اور مصیبتوں میں ڈال دیتی ہیں۔(السعدی؍۵۶۶)\nنگاہ نیچی رکھنے کے دوفائدے ذکر کیجئے.\nوَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ\nزیب وزینت کوظاہر کرنے سے منع کردیا گیا تاکہ یہ معلوم ہوجائے کہ جب زیب وزینت پر نگاہ ڈالنے سے روک دیا گیا کیونکہ یہ بدن کے ان مقامات پرہوتے ہیں تو بذات خود ان جگہوں کو دیکھنا بدرجہ اولیٰ منع ہوگا اور اس کی حرمت اور بڑھ کر ہوگی۔نیز یہ اس بات پر بھی دلیل ہے کہ عورتیں پردے کے معاملہ میں زیادہ محتاط رہیں اور بے پردگی کے معاملہ میں اللہ سے ڈریں۔ (آلوسی: ۹؍۳۳۵)\nزیب وزینت کو ظاہر کرنے سے روکا گیا ہے۔اس سے کیا پتہ چلتا ہے؟\nوَلَا يَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِيُعۡلَمَ مَا يُخۡفِينَ مِن زِينَتِهِنَّۚ\nان جیسی آیتوں سے“سدِّ ذرائع” والا قاعدہ بنایا گیا ہے کہ کوئی چیز گرچہ جائز ہو لیکن وہ کسی حرام تک پہنچاتی ہویا اس کی وجہ سے حرام میں واقع ہونے کا خوف ہو۔ تو وہ ممنوع ہوگی چنانچہ زمین پر پیر مارنااصلاًجائز ہے لیکن چونکہ یہی چیز عورت کی زیب وزینت کے پتہ چلنے کا سبب ہے اس لئے اس کے لئے ممنوع ہے۔ (السعدی؍۵۶۷)\nاس آیت سے کس اصولی قاعدے کا پتہ چلتا ہے؟\nوَتُوبُوٓاْ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ ٣١\nکتاب وسنت اور اجماع ِامت کی روشنی میں ہر مکلف مومن پر توبہ واجب ہے اور اس کے تین فرائض ہیں: ۱۔گناہوں پر شرمندہ ہو اس طورپر کہ اس نے رب ذوالجلال کی نافرمانی کی ہے،ناکہ اس طورپر کہ اسے بدنی یا مالی نقصان ہوا ہے۔۲۔ بلاتاخیر وسستی کے جس قدر جلد ممکن ہوسکے گناہوں کو بالکل چھوڑدے۔ ۳۔ اس بات کا پختہ عزم کرے کہ دوبارہ گناہوں کا ارتکاب نہیں کریگا۔ اور توبہ کے تین آداب بھی ہیں: ۱۔تواضع اور انکساری کے ساتھ گناہوں کا اعتراف کرے۔۲۔ زیادہ سے زیادہ توبہ واستغفار کرے اور اللہ کے سامنے روئے اور گڑگڑائے۔۳۔ پچھلے گناہوں کو مٹانے کے لئے زیادہ سے زیادہ نیکیوں کا کام کرے۔(ابن جزی: ۲؍۹۰)\nتوبہ کے فرائض بیان کیجئے اور اللہ کے نبی یونس علیہ السلام کی دعا کی روشنی میں اللہ کے سامنے اعتراف ِگناہ کے طریقے اور اس کے ادب کی کوئی مثال پیش کیجئے.\nوَتُوبُوٓاْ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ ٣١\nتوبہ کی ترغیب دلانے والی چیزیں سات ہیں: ۱۔ سزا کا خوف، ۲۔ثواب کی امید،۳۔ حساب وکتاب سے شرمندگی، ۴۔محبوب کی محبت، ۵۔ قریب اور نگرانی کرنے والےاللہ کی نگرانی، ۶۔ رب کے سامنے کھڑے ہونے کی کی عظمت،۷۔ نعمتوں کا شکریہ۔ (ابن جزی: ۲؍۹۰)\nوہ کون سی چیزیں ہیں جو توبہ پر ابھارتی ہیں؟\nwords\nإِلاَّ مَا ظَهَرَ مِنهَامگر وه ظاهري لباس جس كو عادت كے مطابق پهنا جائے اور اس ميں فتنه نه هو.\nعَلَى جُيُوبِهِنَّسينے كي كھلي جگه ۔ پس وه اپنے چهروں كو ڈھانك ليں.\nلِبُعُولَتِهِنَّاپنے شوهروں كے ليے.\nغَيرِ أُولِي الإِربَةِوه مرد جنهيں خواتين ميں كوئي دلچسپي نه هو ۔ جيسے نيم مجنون / مست سائيں."],[354,"§النور\ndeeds\nغیر شادی شدہ افراد کے نکاح کی خدمات انجام دینے والے کسی ادارے کو چندہ دیجئے.\nاللہ سے دعا مانگئے کہ آپ کو اپنے نور کی ہدایت دے.\nصبح اور شام کے اذکار مسجد میں ہی پڑھئے.\nguid\nمفلسی نکاح میں رکاوٹ نہیں ہے بلکہ بعض دفعہ نکاح مالداری کا ذریعہ بن جاتا ہے.\nقرآن میں بیان کئے گئے قصوں کو جاننے کی کوشش کیجئے بیشک ان میں واضح دلائل اور عبرت ونصیحت کی بیش قیمت باتیں ہیں.\nفراست کے اسباب میں سے یہ ہے کہ بندے کو اللہ کے نور کی ہدایت مل جائے۔اللہ تعالیٰ نے اس سورت میں اس نور کے حصول کے اسباب، مواقع اور اس نور سے محرومی کی وجوہات ذکر کی ہیں.\nrefl\nوَأَنكِحُواْ ٱلۡأَيَٰمَىٰ مِنكُمۡ وَٱلصَّٰلِحِينَ مِنۡ عِبَادِكُمۡ وَإِمَآئِكُمۡۚ إِن يَكُونُواْ فُقَرَآءَ يُغۡنِهِمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ ٣٢\nطہارت وپاکیزگی کے حکم کے بعد ایسی چیزوں کی طرف رہنمائی کی گئی جو اس میں مددگار ثابت ہوں،جو مومن مردوں اور مومنہ عورتوں کے عصمتوں کی حفاظت کریں اور ان کی نگاہوں کو جھکاکے رکھیں۔چنانچہ ولی حضرات کو یہ حکم دیا کہ غیرشادی شدہ عورتوں کی شادیاں کرائیں اور انہیں بلاشادی نہ چھوڑیں؛ اسی میں ان کے لئے اور اُن مردوں کے لئے عصمت کی حفاظت ہے جو اُن سے شادیاں کریں گے۔ (ابن عاشور: ۱۸؍۲۱۵)\nنگاہوں کے جھکانے اور عفت اختیار کرنے کا حکم دینے کے ساتھ قرآن کریم نے ایسے اسباب وذرائع کا بھی ذکر کیا جو اس کے مددگار ہوسکیں۔ آیت کریمہ اس بات پر کیسے دلالت کرتی ہے؟\nوَأَنكِحُواْ ٱلۡأَيَٰمَىٰ مِنكُمۡ وَٱلصَّٰلِحِينَ مِنۡ عِبَادِكُمۡ وَإِمَآئِكُمۡۚ إِن يَكُونُواْ فُقَرَآءَ يُغۡنِهِمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ ٣٢\nچونکہ فطری طور پر آدمی کے اندر رزق کے کم ہوجانے کا خوف رہتا ہےاسی لئے اگر کوئی شخص یہ کہے کہ آدمی بسااوقات محتاجگی کی وجہ سے شادی کے لائق نہیں ہوتا؛ تو ایسے شخص کو اللہ نے یہ کہہ کر جواب دیا کہ اگر وہ فقیر ہوں اور شادی کرلیں تو اللہ انہیں اپنے فضل سے مالدار کردے گا کیوں کہ اللہ نے ہر ایک کے لئے اس کا رزق مقدر کردیا ہے لہذا کسی کی محتاجگی تمہیں اس کی شادی کرنے سے نہ روکے۔سیدنا ابوبکر صدیق رضی اللہ عنہ سے مروی ہے کہ انہوں نے فرمایا: تم نکاح کے حکم میں اللہ کی اطاعت کرو وہ تمہیں مالدار بنانے کا اپنا وعدہ پورا کریگا۔ (بقاعی: ۱۳؍۲۶۵)\nمالداربننے کا وہ کون سا سبب ہے جس کی آیت کریمہ نے وضاحت کی ہے؟\nوَلۡيَسۡتَعۡفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغۡنِيَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ\nجو لوگ شادی کا شوق رکھتے ہیں لیکن نکاح کے لئے جو اسباب وذرائع اور بنیادی چیزیں ہوتی ہیں انہیں پورا کرنے سے وہ عاجز ہوتے ہیں لہذا ایسی چیز کی طرف ان کی رہنمائی کی گئی جو اُن کے لئے زیادہ مناسب اور زیادہ بہتر ہے یعنی وہ پاکدامنی اختیار کرلیں اور اپنے نفس کی حفاظت کریں۔ (آلوسی: ۹؍۳۴۴)\nغیر شادی شدہ شخص کو ہم کیا نصیحت کریں؟ نیز اللہ نے ان سے کیا وعدہ کیا ہے؟\nوَلۡيَسۡتَعۡفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغۡنِيَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ\nاللہ نے پاکدامنی کا حکم دیا ہے یعنی حرام سے اپنے دامن کو بچانے کی کوشش ہر وہ شخص کرے جو شادی کی طاقت نہ رکھتا ہو چنانچہ اللہ تعالیٰ کے اس فرمان: (لا يَجِدونَ نِكاحًا) کا مطلب ہوگاکہ جو لوگ نکاح کی طاقت نہیں رکھتے۔چاہے جس وجہ سے وہ شادی کرنے سے معذور ہو۔ (ابن جزی: ۲؍۹۱)\nجسے نکاح کی طاقت نہ ہو اس پر کیا واجب ہے؟\nٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ نُّورٌ عَلَىٰ نُورٖۚ يَهۡدِي ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُۚ\nاللہ سبحانہ وتعالیٰ نے غض بصر والی آیتوں کے معاًبعد نور والی آیت کا ذکر کیا اور فرمایا: (الله نُورُ السَّمَاوَاتِ وَالأَرضِ) شاہ بن شجاع کرمانی کی فراست کبھی خطانہیں ہوئی،وہ کہا کرتے تھے: جس نے اپنے ظاہر کو اتباع سنت کے ذریعہ اور باطن کو ذکر ومراقبہ کی پابندی کے ذریعہ معمور کیا اور حرام چیزوں سے اپنی نگاہ کو دوررکھا اور خواہشات ِنفسانی سے بچا رہا اور پانچویں یہ کہ حلال کھایا تو اس کی فراست کبھی خطانہیں کریگی۔اور اللہ تعالیٰ بندے کو اس کے عمل پر اسی کی جنس کا بدلہ دیتا ہے۔ چنانچہ بندہ اگرحرام چیزوں سے اپنی نگاہ جھکاکررکھے گا تو اللہ تعالیٰ اسی جنس سے اسے بہتر بدلہ دے گا اور اس کی بصیرت کی روشنی کو تیز کردے گا۔ (ابن تیمیہ: ۴؍۵۱۳)\nنگاہ جھکانے کے حکم کے بعد نور والی آیت کیوں آئی ہے؟\nنُّورٌ عَلَىٰ نُورٖۚ يَهۡدِي ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُۚ\nاللہ تعالیٰ کے فرمان: (نُورٌ عَلَى نُورٍ) کے بارے میں بعض سلف نے کہا ہے:یہ مومن ہے جو حکمت کی باتیں کرتا ہے گرچہ اس بارے میں کتاب و سنت کی کوئی بات نہ سنی ہو البتہ اگر کوئی بات سنی ہو تو یہ “ نُوْرٌ عَلٰى نُوْرٍ” ہوجائے گا چنانچہ ایمان کا وہ نور جو دل میں ہے قرآن کے نور سے موافق ہوجائے گا۔(ابن تیمیہ: ۴؍۵۱۳)\nایک مومن کے لئے دونور کب اکٹھا ہوتے ہیں؟\nفِي بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرۡفَعَ وَيُذۡكَرَ فِيهَا ٱسۡمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ ٣٦\n(يُسَبِّحُ لَهُ فِيهَا) یعنی ان گھروں میں وہ نماز پڑھتا ہے اور خصوصی طور پر اس کی پاکی بیان کرتا ہے(بِالغُدُوِّ) یعنی صبح کو نماز پڑھ کر(والآصالِ) یعنی شام کے وقت بقیہ نمازیں پڑھ کر۔ چنانچہ یہ اپنے اعمال کو اللہ کے ذکر سے شروع اور ختم کرتے ہیں تاکہ درمیان میں ان کی حفاظت کی جائے اور اُن کی ہر طرح کی سرگرمیوں میں برکت پیدا ہو۔ (بقاعی: ۱۳؍۲۷۸)\nایک مسلمان کا اپنے دن کو نماز اور ذکر الٰہی سے شروع کرنے اور ختم کرنے میں کیا فائدہ ہے؟\nwords\nالأَيَامَىجس كا شوهر نه هو.\nوَإِمَائِكُماور تمهاري باندياں.\nالبِغَاءِزنا.\nتَحَصُّنًاپاكدامني كے ساتھ.\nكَمِشكَاةٍديوار كي كواڑ/ الماري.\nدُرِّيٌّروشن."],[355,"§النور\ndeeds\nجیسے ہی اذان سنیں اپنے تمام کام چھوڑکر تکبیرتحریمہ کے ساتھ نماز کی پابندی کریں.\nنور او ر ہدایت صرف اللہ تعالیٰ سے ہی مانگئے بیشک ان چیزوں کا وہی تنہا مالک ہے.\n“سُبحَانَ اللّٰهِ وَبِحَمْدِهٖ، سُبحَانَ اللّٰهِ الْعَظِيْم” سوبارپڑھئے.\nguid\nقیامت کے دن امن پانے کا ایک سبب یہ بھی ہے کہ دنیا میں اللہ سے ڈرا جائے.\nاس آیت میں کافروں کے دینی کاموں کی بربادی کا بیان ہے.\nبارش ہوتے وقت اللہ سے دعا مانگئے کہ اس وقت دعا قبول ہوتی ہے.\nrefl\nرِجَالٞ لَّا تُلۡهِيهِمۡ تِجَٰرَةٞ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ\n(رجال)اس لفظ سے ان کی اولوالعزمی اور بلند ہمتی کا پتہ چلتا ہے جن کی وجہ سے یہ ان مساجد کو آبادکرتے ہیں جو اِس سرزمین پر اللہ کا گھر، نیز اس کی عبادت،اس کا شکر بجالانے،اسے ایک جاننے اور اسے پاک کرنے کی جگہیں بھی ہیں۔ (ابن کثیر: ۳؍۲۸۴)\nمسجدوں کو آباد کرنے والوں کو ”رجال“ یعنی مرد کہنے سے کیا فائدہ ہے؟\nرِجَالٞ لَّا تُلۡهِيهِمۡ تِجَٰرَةٞ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ\nاکثر صحابہ کا کہنا ہے کہ یہ آیت کریمہ ان بازاروالوں کے سلسلہ میں نازل ہوئی ہے کہ جب وہ اذان کی آواز سنتے ہیں تو اپنا سارا کاروبار چھوڑکر نماز کے لئے چلے جاتے ہیں۔سالم بن عبداللہ رحمہ اللہ نے بازار والوں کو نماز کے لئے جاتے ہوئے دیکھا تو فرمایا: یہی لوگ ہیں جنہیں اللہ تعالیٰ نے اپنے اس فرمان: (لا تلهيهم تجارة ولا بيع عن ذكر الله) سے مراد لیا ہے۔(القرطبی: ۱۵؍۲۸۶)\nان لوگوں کی کیا صفتیں ہیں جن کی اللہ تعالیٰ نے اس آیت میں تعریف فرمائی ہے؟\nرِجَالٞ لَّا تُلۡهِيهِمۡ تِجَٰرَةٞ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوۡمٗا تَتَقَلَّبُ فِيهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَٰرُ ٣٧\nچونکہ اکثر لوگوں کے لئے دنیا کا ترک کرنا بہت مشکل ہوتا ہے،مختلف قسموں کی تجارت کے ذریعہ کمانے کی انہیں شدید محبت ہوتی ہے، اکثر حالتوں میں ان چیزوں کا چھوڑدینا ان پر گراں گذرتا ہے اور ان چیزوں پر اللہ تعالیٰ کے حقوق کو مقدم رکھنے سے انہیں بہت تکلیف پہنچتی ہے اسی لئے اللہ تعالیٰ نے ترغیب وترہیب کے ذریعہ سے اس کی طرف دعوت دی ہے،چنانچہ فرمایا: (يخافون يومًا تتقلب فيه القلوب والأبصار) وہ اس دن سے ڈرتے ہیں جس دن ان کے دل الٹ جائیں گے اور آنکھیں پتھرا جائیں گی۔ (السعدی؍۵۶۹)\nاللہ تعالیٰ کے اس فرمان: (يخافون يومًا تتقلب فيه القلوب والأبصار)کے ذریعہ آیت کو کیوں ختم کیا گیا؟\nلِيَجۡزِيَهُمُ ٱللَّهُ أَحۡسَنَ مَا عَمِلُواْ وَيَزِيدَهُم مِّن فَضۡلِهِۦۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ ٣٨\nاللہ نے نیکیوں پر بدلہ کا ذکر کیا البتہ برائیوں پر بدلہ کا ذکر نہیں کیا حالانکہ ان پر بھی بدلہ ملے گا،اس کی دووجہیں ہیں۔پہلی وجہ: یہ ترغیب کا مقام ہے، اسی لئے صرف رغبت دلانے پر اکتفا کیا گیا۔دوسری وجہ: دراصل یہ صفت ایسے لوگوں کی ہے جن سے گناہ کبیرہ نہیں ہوتے ہیں چنانچہ ان کے صغیرہ گناہ معاف کردئیے۔ (اس طور پر ان کے پاس گناہ بچے ہی نہیں جن کا تذکرہ ہوتا۔)(القرطبی: ۱۵؍۳۰۴)\nبرائیوں کو چھوڑکر صرف نیکیوں پر بدلہ کا ذکر کیوں کیا گیا؟\nوَٱلَّذِينَ كَفَرُوٓاْ أَعۡمَٰلُهُمۡ كَسَرَابِۢ بِقِيعَةٖ يَحۡسَبُهُ ٱلظَّمۡـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمۡ يَجِدۡهُ شَيۡـٔٗا\nکافر گمان کرے گا کہ اس نے عمل کرکے کچھ نیکیاں جمع کرلی ہیں لیکن جب قیامت کے دن اللہ سے ملاقات کرے گا اور حساب وکتاب کے ساتھ اس کے اعمال کا محاسبہ ہوگا تب پتہ چلے گا کہ حقیقت میں اس کا کوئی عمل مقبول نہیں ہوا۔کیونکہ اس کے پاس یا تو اخلاص نہیں تھا یا اس نے شریعت کی پابندی نہیں کی تھی جیسا کہ اللہ تعالیٰ کا فرمان ہے: ﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾(سورۂ فرقان:۲۳)انہوں نے جو بھی اعمال کئے تھے ہم نے ان کی طرف متوجہ ہو کر انہیں بکھرا ہوا گردوغبار بنادیا۔(ابن کثیر: ۳؍۲۸۶)\nقیامت کے دن اعمال کے برباد اور مردود ہونے کا کیا سبب ہے؟\nوَٱلَّذِينَ كَفَرُوٓاْ أَعۡمَٰلُهُمۡ كَسَرَابِۢ بِقِيعَةٖ يَحۡسَبُهُ ٱلظَّمۡـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمۡ يَجِدۡهُ شَيۡـٔٗا\nجب اللہ تعالیٰ نے مومنوں کا حال بیان کردیا تو اس کے فوراً بعد کافروں کے اعمال کی دومثالیں بیان کیں۔ان میں سے پہلی مثال آخرت میں ان کے اعمال کی حالت کوبیان کرتی ہے اور یہ کہ انہیں ان اعمال کا کوئی فائدہ نہیں ہوگابلکہ ان کا اجروثواب ویسے ہی مٹ جائیگا جیسے سراب مٹ جاتاہے۔ “سراب” کہتے ہیں اس چیز کو جو صحراء میں سطح ِ زمین پر دوپہر کے وقت سورج کی تیز روشنی میں دورسے دکھائی دیتی ہے۔بظاہر ایسا لگتا ہے کہ سطحِ زمین پربہتا ہوا پانی ہے (ابن جزی: ۲؍۹۴)\nمشرکین بھی عبادت کرتے ہیں لیکن شرک کے ساتھ۔ ایسی صورت میں قیامت کے دن ان کا انجام کیا ہوگا؟\nأَلَمۡ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلطَّيۡرُ صَٰٓفَّٰتٖۖ كُلّٞ قَدۡ عَلِمَ صَلَاتَهُۥ وَتَسۡبِيحَهُۥۗ\nتمام حیوانوں میں سے صرف پرندوں کا خصوصی طور پر ذکر کیا گیا ہے کیونکہ یہی آسمان وزمین کے درمیان ہوتے ہیں۔ایسی صورت میں یہ ان جانداروں کے حکم میں نہیں آئیں گے جو آسمان وزمین میں رہتے ہیں۔(القرطبی: ۳؍۳۰۶)\nآسمان وزمین میں موجود چیزوں کے ذکر کے بعد پرندوں کا خصوصی ذکر کیوں کیا گیا؟\nwords\nكَسَرَابٍسراب جيسا/ جو كه صحرا ميں دوپهر كو پاني كي طرح نظر آتا هے.\nبِقِيعَةٍپست اور برابر كي زمين.\nلُجِّيٍّگهرا.\nيَغشَاهُاس پر بلند هوتي هے.\nصَآفَّاتٍهوا ميں پر پھيلائے هوئے.\nيُزجِيوه چلاتاهے."],[356,"§النور\ndeeds\nمخلوق کی مختلف اقسام پر غور کیجئے پھر اپنی خلقت کی درستی اور حسن پر اللہ کا شکر ادا کیجئے.\nاللہ سے دعا مانگئے کہ آپ کو صراط مستقیم کی ہدایت دے.\nبذریعہ پیغام اللہ کے فیصلہ پر اعتراض کے نقصانات بتائیے نیز کہ یہ منافقین کی صفات میں سے ہے.\nguid\nاچھی بصیرت والے سمجھدار لوگ ہی کائنات میں پھیلی ہوئی اللہ کی نشانیوں سے نصیحت حاصل کرتے ہیں.\nواجب ہے کہ ہم ہر حال میں شریعت کی تابعداری کریں خواہ اس کا فیصلہ ہماری خواہش کے موافق ہو یا مخالف.\nاللہ کا تقویٰ نیز اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی اطاعت باعث فضیلت ہے اور ان اچھی صفات والے ہی جہنم سے نجات پاکر جنت میں داخل ہونے والے کامیاب لوگ ہیں.\nrefl\nيُقَلِّبُ ٱللَّهُ ٱلَّيۡلَ وَٱلنَّهَارَۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي ٱلۡأَبۡصَٰرِ ٤٤\nیعنی یہ عبرت اور نصیحت ہر اس شخص کے لئے ہے جو صاحب ِبصیرت ہو،عبرت ونصیحت کو سمجھتا ہو اور باربار اس کا مراجعہ کرتا ہو۔اس آیت میں “الْاَبْصَارِ” بصر کی جمع ہے اور اس کا معنیٰ بصیرت ہے سابقہ معانی کے برخلاف جیسا پہلے گزرا۔لیکن یہ بھی کہا گیا ہے کہ ظاہری بصارت کے معنی میں ہے جیسا کہ بظاہر سمجھ میں آرہا ہے اور یہاں “بصائر” نہ لاکر“الْاَبْصَارِ”ذکر کرنے کا مقصد عبرت ونصیحت کے بالکل واضح ہونے پر دلالت کرنے کی خبر دینا ہے۔ (الوسی: ۹؍۳۸۴)\nآیت میں لفظ “بصائر” نہ لاکر “الْاَبْصَارِ”لایا گیا۔اس کا کیا فائدہ ہے؟\nلَّقَدۡ أَنزَلۡنَآ ءَايَٰتٖ مُّبَيِّنَٰتٖۚ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ٤٦\n(آيات مبينات) ہر اس الٰہی نشانی کو عام ہے جنہیں اللہ نے عبرت ونصیحت کے لئے بنایا ہے اور جس بھی نشانی کا ذکر اللہ نے اپنی کتاب میں کیا ہے وہ بطور نصیحت اور تنبیہ ہے۔ (ابن عطیہ: ۴؍۱۹۱)\nوہ کون سی نشانیاں ہیں جن کے ذریعہ اللہ تعالیٰ مومن بندوں کو ہدایت دیتا ہے؟\nوَيَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعۡنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٞ مِّنۡهُم مِّنۢ بَعۡدِ ذَٰلِكَۚ وَمَآ أُوْلَٰٓئِكَ بِٱلۡمُؤۡمِنِينَ ٤٧\nان آیتوں سے پتہ چلا کہ ایمان صرف زبان سے اقرار کرلینے کو نہیں کہتے بلکہ اس اقرار کے ساتھ عمل کا ہونا بھی ضروری ہے۔اور اسی لئے ان لوگوں کے ایمان کی نفی کردی گئی جنہوں نے اطاعت ِالٰہی سے منہ پھیر لیا۔ (السعدی؍۵۷۲)\nآیت سے عقیدہ کی ایک اہم بات معلوم ہوتی ہے۔اسے ذکر کیجئے.\nوَإِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحۡكُمَ بَيۡنَهُمۡ إِذَا فَرِيقٞ مِّنۡهُم مُّعۡرِضُونَ ٤٨\nمروی ہے کہ ایک منافق جس کا نام بشر تھا،اس کے اور ایک یہودی کے درمیان جھگڑا ہوگیا۔یہودی نے اس مقدمہ کو رسول اللہ صلی اللہ علیہ وسلم کے پاس لے جانا چاہا لیکن منافق نے اس سے انکار کردیا کیونکہ وہ باطل پر تھا،اس نے یہودی سےاس مقدمہ کو کعب بن اشرف کے پاس لے جانے کا مطالبہ کیا ۔اسی تعلق سے یہ آیت نازل ہوئی۔ زہراوی نے حسن بن ابی الحسن کے واسطہ سے روایت کی ہے کہ جھگڑے کی صورت میں اگر فریق ِمخالف کسی مسلم حاکم کے پاس مقدمہ لے جانا چاہے اور دوسرا انکار کردے تو وہ ظالم ہوگا۔ (ابن عطیہ: ۴؍۱۹۱)\nجھگڑے کے وقت اگر فیصلہ کو شریعت کی طرف لایا جائے تو اس وقت ایک مومن کا کیا موقف ہونا چاہئے؟\nأَمۡ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيۡهِمۡ وَرَسُولُهُۥۚ\nاس آیت نے دنیا وآخرت دونوں جگہ کامیابی کے اسباب کو اکٹھاکردیا ہے۔ (ابن عاشور: ۱۸؍۲۷۶)\nیہ آیت کریمہ جوامع الکلم میں سے مانی جاتی ہے۔اس کی وضاحت کیجئے.\nوَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخۡشَ ٱللَّهَ وَيَتَّقۡهِ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ ٥٢\nجمعت الآية أسباب الفوز في الآخرة، وأيضًا في الدنيا. ابن عاشور:۱۸/۲۷۶.\nتعد الآية الكريمة من جوامع الكلم، بين ذلك.\nوَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِنۡ أَمَرۡتَهُمۡ لَيَخۡرُجُنَّۖ قُل لَّا تُقۡسِمُواْۖ طَاعَةٞ مَّعۡرُوفَةٌۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ ٥٣\nیہ اس طرح ہے کہ منافقین رسول اللہ صلی اللہ علیہ وسلم سے کہتے تھے:آپ جہاں کہیں بھی رہیں ہم آپ کے ساتھ رہیں گے،اگر باہر نکلیں گے تو ہم بھی نکلیں گے، اگر قیام کریں گے تو ہم بھی قیام کریں گے اور اگرآپ ہمیں جہاد کا حکم دیں گے تو ہم جہاد کریں گے۔اس پر اللہ تعالیٰ نے فرمایا: (قل لا تقسموا) یعنی: فرمادیجئے : تم قسم نہ کھاؤ۔ اور اس طرح بات پوری ہوگئی۔ پھر اللہ تعالیٰ نے آگے ارشاد فرمایا: (طاعة معروفة) یعنی:یہ اسی طرح زبان سے دعویٰ کرنے والی اطاعت ہے جو دل سے نہیں کہی جارہی ہے۔اور یہ معروف ہے۔ یعنی یہ مشہور ہے کہ تم لوگ اس طرح کاجھوٹ بولتے رہتے ہواور ایسی باتیں کہتے رہتے ہو جوکرتے نہیں۔(البغوی: ۳؍۳۰۹)\nکیا دل سے اعتقاد کئے بغیر صرف زبان سے اقرار کرلینا کافی ہے؟\nwords\nمُذعِنِينَاطاعت گزار/ مان لينے والے.\nمَرَضٌبيماري / نفاق.\nارتَابُوانبوت ميں شك كيا.\nيَحِيفَوه ظلم كرتا هے.\nجَهدَ أَيمَانِهِمكوشش كركے بهت سخت مغلظ قسميں كھانا."],[357,"§النور\ndeeds\nپنج وقتہ نمازیں باجماعت او ر خشوع کے ساتھ پڑھئے کہ یہ نماز قائم کرنے کی اہم شکل ہے.\nاپنے مال میں سے کچھ نہ کچھ صدقہ ضرور دیتے رہئے.\nاپنے آس پاس والوں سے مل کر اجازت طلبی کے کچھ آداب ایک دوسرے کو بتائیے.\nguid\nآیات قرآنی اور احادیث صحیحہ کی اتباع کرنا سعادت دارین کا ضامن ہے جبکہ ان کی مخالفت گمراہی اور خسارہ ہے.\nزمین میں غلبہ دینے اور حاکم بنانے کا الٰہی وعدہ اللہ کی عبادت اور شرک سے اجتناب کے ساتھ مشروط ہے.\nموجود زمانہ کی طاقتور کافر حکومت اور قدیم زمانہ کی کوئی کافر امت جسے اللہ نے ہلاک کردیا ان دونوں کے بیچ موازنہ کیجئے اور ان میں موجود قدر مشترک پر غور کیجئے.\nrefl\nقُلۡ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡهِ مَا حُمِّلَ وَعَلَيۡكُم مَّا حُمِّلۡتُمۡۖ وَإِن تُطِيعُوهُ تَهۡتَدُواْۚ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ٥٤\n(وعليكم ما حملتم) والے دھمکی بھرے جملے کے بعد (وإن تطيعوه تهتدوا) کا جملہ لانا دراصل اطاعت کے کاموں کی طرف رغبت دلانا مقصود ہے۔ (ابن عاشور: ۱۸؍۲۸۱)\nاس آیت کریمہ میں ترغیب وترہیب دونوں موجود ہیں۔ وضاحت کریں.\nقُلۡ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡهِ مَا حُمِّلَ وَعَلَيۡكُم مَّا حُمِّلۡتُمۡۖ وَإِن تُطِيعُوهُ تَهۡتَدُواْۚ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ٥٤\nیعنی:اگر تم لوگ رسول اللہ صلی اللہ علیہ وسلم کی اپنے قول وعمل کے ذریعہ اطاعت کروگے تو سیدھے راستے کی طرف ہدایت پاجاؤگے؛گویا بغیر اطاعت ِ رسول صلی اللہ علیہ وسلم کے ہدایت پانے کی کوئی سبیل نہیں ہے اور اس کے بغیر ناممکن ہی نہیں بلکہ محال ہے۔ (السعدی؍۵۷۳)\nکیا اطاعت ِرسول صلی اللہ علیہ وسلم کے بغیر ہدایت ممکن ہے؟\nوَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَيَسۡتَخۡلِفَنَّهُمۡ فِي ٱلۡأَرۡضِ كَمَا ٱسۡتَخۡلَفَ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَلَيُمَكِّنَنَّ لَهُمۡ دِينَهُمُ ٱلَّذِي ٱرۡتَضَىٰ لَهُمۡ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعۡدِ خَوۡفِهِمۡ أَمۡنٗاۚ\nآیت اس بات پر واضح طور سے دلالت کررہی ہے کہ امت کے خلفاء جیسے ابوبکر،عمر،عثمان،علی، حسن اور معاویہ رضی اللہ عنہم سے اللہ تعالیٰ راضی ہے کیونکہ انہیں بالکل اس طرح خلیفہ چن لیا تھا جیسے پورے طور پر ان سے پہلے لوگوں کو خلیفہ چنا تھااور ان کے ہاتھ پر مشرق سے مغرب تک تمام شہروں کو فتح نصیب کی اور قیصر وکسریٰ کے دلوں میں ان کا رعب ڈال دیا۔(ابن عاشور: ۱۸؍۲۸۶)\nآیت کریمہ صحابہ کرام کی فضیلت پر کیسے دلالت کرتی ہے؟\nوَمَن كَفَرَ بَعۡدَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ٥٥\nاے مسلمانو کی جماعت! ہر طرح کی طاقت وقدرت تمہارے ہی لئے زیب ہے (فأولئك هم الفاسقون) جو لوگ اللہ کی اطاعت سے نکل گئے اور زمین میں فساد برپاکیا نہ وہ کسی خیر کے لائق ہیں اور نہ ان کے اندر خیر وبھلائی کی کوئی اہلیت ہے کیونکہ جو کوئی اپنے اقتدار،غلبہ اور موانع ِایمان کے عدم ِ وجود کے وقت ایمان کو ترک کردیتا ہے تو یہ چیز اس کے فساد ِنیت اور خبث ِباطن پر دلالت کرتی ہے کیونکہ اس کے لئے خبث ِباطن کے سوا ترک دین کا کوئی داعیہ موجود نہیں ہے۔ (السعدی؍۵۷۳)\nقدرت وطاقت کے بعد اللہ تعالیٰ نے کافروں کو فسق وفجور سے کیوں متصف کیا؟\nوَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَطِيعُواْ ٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ ٥٦\nاللہ تبارک وتعالیٰ نے نماز کو قائم کرنے اور زکاۃ ادا کرنے کا حکم دیا ہے اور یہ دوعبادتیں سب سے زیادہ جلیل القدر عبادات ہیں جو حقوق اللہ اور حقوق العباد یعنی معبود کے ساتھ اخلاص اور بندوں کے ساتھ احسان کو جامع ہیں،پھر اس حکم پر عطف کے ساتھ عام حکم دیا،فرمایا: (وأطيعوا الرسول) رسول صلی اللہ علیہ وسلم کی اطاعت کرو(لعلكم) شایدجب تم ان امور کا خیال رکھوگے (ترحمون) تو تم پر رحم کیا جائیگا۔اب جو کوئی رحمت کا طلبگار ہے تو اس کے حصول کا یہی طریقہ ہے اور جو بھی نماز و زکاۃ کی ادائیگی او ر رسول اللہ صلی اللہ علیہ وسلم کی اطاعت کے بغیر رحمت کی امید رکھتا ہے تو اس کی تمنائیں جھوٹی ہیں اور وہ جھوٹی آرزوؤں میں گرفتار ہے۔ (السعدی؍۵۷۳)\nان تمام احکامات میں سے جن میں اطاعت رسول صلی اللہ علیہ وسلم واجب ہوتی ہے صرف نماز اور زکاۃ کو بطور خاص کیوں ذکر کیا گیا ہے؟اور اس شخص کے بارے میں کیا خیال ہے جو نماز وزکاۃ کی ادائیگی میں کوتاہی کرے،اللہ کی نافرمانی کرے اور اس کی رحمت کی تمنا بھی کرے؟\nلَا تَحۡسَبَنَّ ٱلَّذِينَ كَفَرُواْ مُعۡجِزِينَ فِي ٱلۡأَرۡضِۚ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَلَبِئۡسَ ٱلۡمَصِيرُ ٥٧\nآیت میں (في الأرض)کو (مُعْجِزِيْنَ)کے لئے بطور ظرف لایا گیا ہے تاکہ عاجز نہ کرسکنے کا معاملہ زمین کے تمام اجزاء کو شامل ہوجائے۔یعنی آپ ایسا بالکل نہ سمجھیں کہ یہ کافر اللہ تعالیٰ کو عاجز کردیں گے۔یقینا وہ اللہ تعالیٰ کی پکڑ میں آئیں گے اور خواہ وہ زمین کے کسی بھی خطہ میں رہیں اور کہیں بھی بھاگ کر جائیں اللہ انہیں ضرور ہلاک کریگا۔ (الوسی: ۹؍۳۹۸)\nآیت کریمہ میں (في الأرض) جملہ کا کیا فائدہ ہے؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِيَسۡتَـٔۡذِنكُمُ ٱلَّذِينَ مَلَكَتۡ أَيۡمَٰنُكُمۡ وَٱلَّذِينَ لَمۡ يَبۡلُغُواْ ٱلۡحُلُمَ مِنكُمۡ ثَلَٰثَ مَرَّٰتٖۚ\nآیت میں ان تین اوقات کو خاص کیا گیا ہے کیونکہ یہ اوقات خلوت ہیں نیز کپڑے اتار کر سونے کے اوقات ہیں۔لہذا ہوسکتا ہے کہ ان اوقات میں انسان ایسی حالت میں ہوکہ اسے یہ پسند نہ آئے کہ اُسے کوئی اُس حالت میں دیکھے۔ (القرطبی: ۱۵؍۳۱۳)\nخصوصی طور پر ان تین اوقات میں اجازت لینے کا حکم کیوں دیا گیا ہے؟\nwords\nعَلَيهِ مَا حُمِّلَرسول كي وهي ذمه داري هے جو تبليغ كا كام ان كے سپرد هے.\nوَعَلَيكُم مَا حُمِّلتُماور آپ پر اس كي اطاعت گزاري كي ذمه داري هے.\nمُعجِزِينَبھاگ كر عذاب سے بچنے والے.\nجُنَاحٌهرج / گناه."],[358,"§النور\ndeeds\nاپنے بھائیوں اور بہنو ں کے پاس جانے سے پہلے اجازت مانگئے.\nاپنے گھر کی عورتوں کو حجاب،پاکدامنی اور حیاء کی نصیحت کرتے رہئے کیونکہ اللہ تعالیٰ نے بوڑھی عورتوں کو بھی تنبیہ کی ہے.\nگھر میں داخل ہونے سے پہلے “بِسْمِ اللّٰهِ ” کہئے اور سلام کیجئے.\nguid\nدیکھئے شریعت نے کس طرح فتنوں کے دروازے اور فساد کی کھڑکیاں بند کردیں۔ ہمیں اس علم کو حاصل کرنے کی کتنی شدید ضرورت ہے!\nغور کیجئے کہ شریعت کتنی آسان ہے! اور کس طرح سب لوگوں اور خاص طور سے عذر والوں کے لئے نرم رویہ اپناتی ہے!\nلوگوں کو ہمیشہ انہی الفاظ سے سلام کیجئے جو اللہ نے مشروع کئے ہیں (السلام علیکم و رحمۃ اللہ وبرکاتہ).\nrefl\nوَٱلۡقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّٰتِي لَا يَرۡجُونَ نِكَاحٗا فَلَيۡسَ عَلَيۡهِنَّ جُنَاحٌ أَن يَضَعۡنَ ثِيَابَهُنَّ غَيۡرَ مُتَبَرِّجَٰتِۢ بِزِينَةٖۖ وَأَن يَسۡتَعۡفِفۡنَ خَيۡرٞ لَّهُنَّۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ ٦٠\nان احکام میں بوڑھی عورتوں کو خاص کردیا گیا کیونکہ نفس ان کی طرف مائل نہیں ہوتااور مردوں کو ان میں چاہت نہیں ہوتی اسی لئے ان کے لئے وہ جائز کردیا گیا جو دوسری عورتوں کے لئے جائز نہیں ہے اور اس طور سے ان کے اوپر سے پریشان کن حفاظتی عمل سے انہیں بچالیا گیا۔ (القرطبی: ۳۴۰)\nمذکورہ حکم کو بوڑھی عورتوں کے ساتھ کیوں خاص کردیا گیا؟نیز اس آیت سے ان عورتوں کے بارے میں آپ کیا سمجھتے ہیں جو بوڑھی نہیں ہیں؟\nوَلَا عَلَىٰٓ أَنفُسِكُمۡ أَن تَأۡكُلُواْ مِنۢ بُيُوتِكُمۡ أَوۡ بُيُوتِ ءَابَآئِكُمۡ أَوۡ بُيُوتِ أُمَّهَٰتِكُمۡ أَوۡ بُيُوتِ إِخۡوَٰنِكُمۡ أَوۡ بُيُوتِ أَخَوَٰتِكُمۡ أَوۡ بُيُوتِ أَعۡمَٰمِكُمۡ أَوۡ بُيُوتِ عَمَّٰتِكُمۡ أَوۡ بُيُوتِ أَخۡوَٰلِكُمۡ أَوۡ بُيُوتِ خَٰلَٰتِكُمۡ أَوۡ مَا مَلَكۡتُم مَّفَاتِحَهُۥٓ أَوۡ صَدِيقِكُمۡۚ\nمذکورہ بالا تمام گھروں میں بغیر اجازت کھاپی لینے میں مضائقہ نہیں ہے او ر اس کی حکمت سیاق ِکلام سے واضح ہے۔ان مذکورہ گھروں میں عادت اور عرف عام کے مطابق قرابت ِقریبہ،تصرف ِکامل اور دوستی کی وجہ سے کھاپی لینے کے معاملہ میں مسامحت برتی جاتی ہے۔اگر ان مذکورہ بالا گھروں میں کھاپی لینے میں عدم مسامحت اور بخل معلوم ہوجائے تو حکمت اور معنی کو مد نظر رکھتے ہوئے نہ کھانا جائز ہوگا اور نہ ہی حرج ختم ہوگا۔(السعدی؍۵۷۵)\nمذکورہ بالا گھروں والے اگر اپنے گھروں سے کھانے کی اجازت نہ دیں تو اس وقت کیا حکم ہوگا؟\nوَلَا عَلَىٰٓ أَنفُسِكُمۡ أَن تَأۡكُلُواْ مِنۢ بُيُوتِكُمۡ أَوۡ بُيُوتِ ءَابَآئِكُمۡ أَوۡ بُيُوتِ أُمَّهَٰتِكُمۡ أَوۡ بُيُوتِ إِخۡوَٰنِكُمۡ أَوۡ بُيُوتِ أَخَوَٰتِكُمۡ\nمذکورہ قرابت داروں کے گھروں کے ذکر کرنے میں بیٹوں کے گھروں کو چھوڑدیا۔اس تعلق سے مفسرین نے کہا ہے کہ ان کاگھر اس حکم (من بيوتكم)میں داخل ہے کیونکہ بیٹے کا گھر اپنا گھر ہوتا ہے۔ (القرطبی: ۱۵؍۳۴۷)\nآیت کے اندر تمام رشتہ داروں کے گھروں کا تذکرہ ہوا،اس بیچ میں بیٹوں کے گھروں کو چھوڑدینے کا کیا سبب ہے؟\nأَوۡ صَدِيقِكُمۡۚ\nاللہ تعالیٰ نے خالص مضبوط قرابت داروں کی فہرست میں دوستی کو بھی شامل کردیا ہے اس لئے کہ محبت اور دوستی کی قرابت بہت مضبوط اور گہری ہوتی ہے۔ ابن عباس رضی اللہ عنہما نے فرمایا:دوست رشتے داروں سے زیادہ مضبوط ہوتا ہے۔دیکھیں جہنمی کس طرح فریاد کرتے ہوئے کہیں گے﴿فَمَا لَنَا مِن شَٰفِعِينَ * وَلَا صَدِيقٍ حَمِيمٖ﴾ (سورۂ شعراء: ۱۰۰-۱۰۱)ہمارا کوئی سفارشی نہیں اور نہ کوئی گہرا دوست ہے ۔(القرطبی: ۱۵؍۳۵۱)\nاللہ تعالیٰ نے دوست کو قرابت داروں کے ساتھ کیوں ملادیا؟\nلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَأۡكُلُواْ جَمِيعًا أَوۡ أَشۡتَاتٗاۚ\nیہاں نفی حرج کے لئے ہے نہ کہ فضیلت کے لئے کیونکہ افضل یہی ہے کہ ایک ساتھ مل کر کھایا جائے۔ (السعدی: ۵۷۵)\nکھانا ایک ساتھ مل کر کھانا افضل ہے یاالگ الگ؟\nفَسَلِّمُواْ عَلَىٰٓ أَنفُسِكُمۡ\nیعنی ہر کوئی ایک دوسرے سے سلام کرے اس لئے سارے مسلمان شفقت،مہربانی اور آپسی محبت میں ایک شخص کی مانند ہیں۔(السعدی؍۵۷۵)\nاللہ تعالیٰ نے اس فرمان: (فسلموا على أنفسكم) کے اندر مسلمانوں کے درمیان ایک باہمی مضبوط رابطہ کی طرف اشارہ کیا ہے۔اس کی وضاحت کیجئے.\nفَإِذَا دَخَلۡتُم بُيُوتٗا فَسَلِّمُواْ عَلَىٰٓ أَنفُسِكُمۡ تَحِيَّةٗ مِّنۡ عِندِ ٱللَّهِ مُبَٰرَكَةٗ طَيِّبَةٗۚ\nسلام وتحیۃ کو برکت سے متصف کیا ہے کیونکہ اس میں دعا ہے اور جسے سلام کیا جاتا ہے اس کے دل میں محبت پیدا ہوتی ہے۔(ابن عطیہ: ۴؍۱۹۷)\nسلام وتحیہ کو برکت سے متصف کرنے کی کیا وجہ ہے؟\nwords\nوَالقَوَاعِدُبوڑھي عورتيں جن كے حيض اور استمتاع كي عمر گزرچكي هو.\nمُتَبَرِّجَاتٍخفيه زينت كو ظاهر كرنے والياں.\nمَا مَلَكتُم مَفَاتِحَهُوه گھر جن كي حفاظت كے ذمه دار تم بنے هو.\nأَشتَاتًامتفرق."],[359,"§النور ، الفرقان\ndeeds\nزندہ اور مردہ سب مسلمان مردوں اورعورتوں کے لئے اللہ سے استغفار کیجئے.\nجب بھی نبی صلی اللہ علیہ وسلم کا نام آئے آپ پر درود ضرور پڑھئے.\nبذریعہ پیغام سنت نبی صلی اللہ علیہ وسلم کی مخالفت کی خطرناکی کو واضح کیجئے.\nguid\nرسول اللہ صلی اللہ علیہ وسلم کی زندگی میں اور وفات کے بعد بھی آپ کی تعظیم واجب ہے اور آپ کے ساتھ بے ادبی حرام ہے.\nسنت رسول صلی اللہ علیہ وسلم کی خلاف ورزی کرنے والے پر سوء خاتمہ کا خوف ہے۔ اللہ ہمیں محفوظ رکھے.\nاللہ تعالیٰ جلد ہی آپ کوآپ کے ہر چھوٹے بڑے عمل کی خبر دیگا لہذا کوشش کیجئے کہ اللہ آپ کو آپ کے بارے میں اچھی اور پسندیدہ باتیں ہی بتائے.\nrefl\nإِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُواْ مَعَهُۥ عَلَىٰٓ أَمۡرٖ جَامِعٖ لَّمۡ يَذۡهَبُواْ حَتَّىٰ يَسۡتَـٔۡذِنُوهُۚ إِنَّ ٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ أُوْلَٰٓئِكَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦۚ\n(عَلَى أَمرٍ جَامِعٍ) یعنی ایسے اہم مسئلہ پر جس پر سارے لوگ متفق ہوجائیں جیسے کسی جنگ کی نوبت پیش آجائے یا نماز کا وقت ہوجائے یا کسی اہم معاملہ کے اچانک پیش آجانے پر مشورے کے لئے سب اکٹھاہوجائیں (لَم يَذهَبوا) یعنی اگر کسی مسئلہ پر فیصلہ کے لئے اکٹھاہوتے ہیں تو رسول اللہ صلی اللہ علیہ وسلم کی اجازت کے بغیر اٹھتے نہیں ہیں۔ (الطبری: ۱۹؍۲۲۸)\nاجازت لینا ایمان کی دلیل ہے اور اجتماعی مسئلہ کی کامیابی کی دلیل ہے۔ آیت کی روشنی میں اس کی وضاحت کریں.\nوَٱسۡتَغۡفِرۡ لَهُمُ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ٦٢\n(واستغفر لهم) اللہ تعالیٰ فرماتا ہے: یعنی ان کے لئے دعا کیجئے کہ اللہ تعالیٰ ان کی غلطیوں کو معاف فرمائے (إن الله غفور) بیشک اللہ تعالیٰ اپنے توبہ کرنے والے بندے کے گناہوں کو معاف فرمانے والا ہے (رحيم) یعنی بہت مہربان ہے،توبہ قبول کرنے کے بعد سزادینے والا نہیں ہے۔ (الطبری: ۱۹؍۲۲۹)\nکسی بھی رہنما کے مہربان اور کامیاب ہونے کے لئے ضروری ہے کہ وہ اپنے ماتحتوں کے لئے ان کی غیر موجودگی میں دعاکرے۔آیت کی روشنی میں اس کی وضاحت کریں.\nلَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ بَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضٗاۚ\nلوگوں کو اس بات سے منع کردیا گیا کہ آپس میں ایک دوسرے کو پکارنے کی طرح رسول اللہ صلی اللہ علیہ وسلم کو نہ پکاریں چاہے لفظ میں ہو یا ہیئت وشکل میں ہو۔ چنانچہ لفظی طور پر “اے محمد!” یا “اے عبداللہ کے بیٹے!” یا “اے عبدالمطلب کے بیٹے!” نہ کہے بلکہ “اے اللہ کے رسول!”یا“اے اللہ کے نبی!” یا آپ کی کنیت کے ساتھ “اے ابوالقاسم!” کہہ کر پکارے۔ اور کیفیت وشکل میں گھر کے باہر سے نہ پکاریں اور اگر آپ نہ نکلیں تو پکارتے ہی نہ رہ جائیں۔ (ابن عاشور: ۱۸؍۳۰۹)\nرسول اللہ صلی اللہ علیہ وسلم کی تعظیم اللہ کی تعظیم ہے۔ آیت کی روشنی میں اس کی وضاحت کیجئے.\nلَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ بَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضٗاۚ\nاس آیت میں رسول اللہ صلی اللہ علیہ وسلم کے حکم کی تعظیم تو ہے ہی اس کے علاوہ اس بات کی جانب اشارہ بھی ہے کہ اپنی جماعت کے شیخ کو امت کے نبی جیسا کہنا بھی منع ہے لہذا گفتگو میں اس کا احترام ضروری ہے اور یہ کہ اسے دوسروں سے ممتاز مانا جائے۔(الوسی: ۹؍۴۱۹)\nایک طالب کے لئے اس کے شیخ،مربی، علماء اور بڑے لوگوں کے ساتھ تعامل کے عمدہ آداب ہیں۔آیت کی روشنی میں اس کی وضاحت کریں.\nتَبَارَكَ ٱلَّذِي نَزَّلَ ٱلۡفُرۡقَانَ عَلَىٰ عَبۡدِهِۦ لِيَكُونَ لِلۡعَٰلَمِينَ نَذِيرًا ١\nقرآن کریم کو “ الْفُرْقَانَ” دووجہوں سے کہا گیا ہے: ۱۔ کیونکہ اس نے حق وباطل اور مومن وکافر کے درمیان فرق کردیا ہے۔ اس لئے کہ اس کے اندر شرعی طور پر تمام حلال وحرام کی وضاحت کردی گئی ہے۔(القرطبی: ۱۵؍۳۶۶)\nقرآن کریم کو “ الْفُرْقَانَ” کیوں کہا گیا؟\nتَبَارَكَ ٱلَّذِي نَزَّلَ ٱلۡفُرۡقَانَ عَلَىٰ عَبۡدِهِۦ لِيَكُونَ لِلۡعَٰلَمِينَ نَذِيرًا ١\nآیت میں مذکور “عَبْدِ”سے مراد ہمارے نبی محمد صلی اللہ علیہ وسلم ہیں۔آپ کے لئے عبد کا لفظ آپ کے شرف وفضیلت کے لئے لایا گیا ہے،نیز یہ بتانے کے لئے کہ آپ صلی اللہ علیہ وسلم عبودیت کے اعلیٰ مراتب پر فائز ہیں اور اس بات سے آگاہ کرنے کے لئے کہ بیشک رسول اللہ کا بندہ ہی ہوتا ہے جس میں نصاریٰ پر رد بھی ہے۔ (الوسی: ۹؍۲۴۲)\nاللہ تعالیٰ نے نزول قرآن کے مقام پر نبی صلی اللہ علیہ وسلم کے لئے عبودیت کو ذکر کیا نہ کہ نبوت ورسالت کو۔اس سے آپ کیا سمجھتے ہیں؟\nوَخَلَقَ كُلَّ شَيۡءٖ فَقَدَّرَهُۥ تَقۡدِيرٗا ٢\nیعنی: اللہ نے ہر چیز کو پیدا کیا اور اسی کے مناسب حال سے سنوارا،نہ اس میں کوئی خلل ہے نہ کوئی فرق۔اور کہا گیا: ہر چیز کی عمر اور رزق مقدر کردیا ہے چنانچہ اسی پیدائش پر تقدیر نافذ ہوتی ہے۔ (البغوی: ۳؍۳۲۱)\nبندوں کی تقدیر بنانے میں اللہ تعالیٰ کی عظمت شان کی تھوڑی وضاحت کریں.\nwords\nأَمرٍ جَامِعٍمسلمانوں كي مصلحت كا اهم كام جس كے ليے جمع هوئے هوں.\nدُعَاءَ الرَّسُولِتمهارا اس طرح آواز دينا: يامحمد! مگر يوں كهو : يا رسول الله !\nيَتَسَلَّلُونَ مِنكُموه تمهارے پاس سے بغير اجازت كے نكل جاتے هيں.\nلِوَاذًاوه ايك دوسرے كے نكلنے كو پرده ميں ركھتے هيں.\nفِتنَةٌآزمائش / شر / عذاب.\nفَقَدَّرَهُاسے مناسب تخليق ميں درست كيا."],[360,"§الفرقان\ndeeds\nیہ دعا مانگئے: “اَللّٰهُمَّ أَحْسِنْ خَاتِمَتِىْ فِىْ الْاُمُوْرِ کُلِّهَا وَاَجِرْنِىْ مِنْ خِزْیِ الدُّنْيا وَعَذابِ الآخِرَةِ”۔ اے اللہ! ہر کام میں میرا انجام بہتر رکھنا اورمجھے دنیا کی رسوائی اور آخرت کے عذاب سے بچانا.\nتوحید کے موضوع پر درس دیجئے یا پیغام بھیجئے جس میں یہ بیان کریں کہ بندوں کے تمام معاملات کا مالک اکیلا اللہ ہی ہے نیز اللہ کے علاوہ نہ کوئی فائدہ دے سکتاہے اور نہ نقصان پہنچا سکتا ہے.\nاللہ تعالیٰ سے مغفرت ورحمت مانگئے.\nguid\nیاد رکھئے کہ اللہ تعالیٰ جب غائب اور مخفی کو بھی جانتاہے تو ظاہر سے متعلق اس کے علم کا کیا عالم ہوگا!\nجھٹلانے والوں کی عادت ہے کہ اللہ کی طرف دعوت دینے والوں کا مذاق اڑاتے اور انہیں تکلیف پہنچاتے ہیں.\nاللہ کے راستہ میں پہنچنے والی تکالیف پر صبر کیجئے۔بیشک رسول اللہ صلی اللہ علیہ وسلم نے اپنی قوم کی جانب سے پہنچنے والی بہت سی تکلیف دہ باتوں پر صبر کیا ہے.\nrefl\nوَٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗ لَّا يَخۡلُقُونَ شَيۡٔٗا وَهُمۡ يُخۡلَقُونَ وَلَا يَمۡلِكُونَ لِأَنفُسِهِمۡ ضَرّٗا وَلَا نَفۡعٗا وَلَا يَمۡلِكُونَ مَوۡتٗا وَلَا حَيَوٰةٗ وَلَا نُشُورٗا ٣\nاللہ تعالیٰ نے اس آیت کریمہ میں یہ ذکر کیاہے کہ وہ معبودان ِباطلہ جن کی مشرکین پرستش کرتے ہیں،وہ چھ صفتوں سے متصف ہیں جن میں سے ہر ایک اس بات کی واضح دلیل ہے کہ اللہ کو چھوڑ کر ان کی پرستش کرنا کسی حال میں درست نہیں ہے بلکہ یہ انتہا درجہ کا ظلم اور بہت بڑی جہالت ہے۔: ۱. انہیں کچھ بھی پیدا کرنے کی طاقت نہیں ہے۔ ۲. وہ سب کے سب مخلوق ہیں جنہیں ہر چیز کے خالق نے پیدا کیا ہے۔ ۳. وہ اپنے لئے کسی نفع ونقصان کے مالک نہیں ہیں۔ ۴. وہ کسی کی موت کے مالک نہیں ہیں۔ ۵. وہ کسی کی حیات کے مالک نہیں ہیں۔ ۶. وہ مرنے کے بعد دوبارہ اٹھانے کے مالک نہیں ہیں۔(شِنقیطی: ۶؍۹)\nکمی کی وہ کون سی صورتیں ہیں جو اللہ کے علاوہ ہر معبود میں پائی جاتی ہیں؟\nقُلۡ أَنزَلَهُ ٱلَّذِي يَعۡلَمُ ٱلسِّرَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ\nراز کی باتوں کا ذکر کیا علانیہ باتوں کو چھوڑکر۔کیونکہ جسے راز کی باتوں کا علم ہوگا وہ علانیہ باتوں کو بدرجہ اولیٰ جانیگا۔(القرطبی: ۱۵؍۳۶۹)\nآیت کریمہ میں علانیہ باتوں کو چھوڑکر صرف راز کی باتوں کاخصوصی طور پر کیوں ذکر کیا گیا؟\nوَقَالُوٓاْ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ٱكۡتَتَبَهَا فَهِيَ تُمۡلَىٰ عَلَيۡهِ بُكۡرَةٗ وَأَصِيلٗا ٥ قُلۡ أَنزَلَهُ ٱلَّذِي يَعۡلَمُ ٱلسِّرَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ غَفُورٗا رَّحِيمٗا ٦\n(إِنَّهُ كَانَ غَفورًا رَحيمًا) ا س سے انہیں توبہ وانابت کی طرف بلانا مقصود ہے اور اس بات کی خبر دینا کہ اس کی رحمت کشادہ ہے نیز اس کی بردباری بہت عظیم ہے اور جو اس سے توبہ کرتا ہے وہ اس کی توبہ قبول کرتا ہے۔یہ وہ لوگ ہیں جنہوں نے جھٹلایا،بہتان باندھا،فسق وفجور کیا،کفر وسرکشی پر اتر آئے نیز رسول صلی اللہ علیہ وسلم اور قرآن کے بارے میں کیا کیا نہیں کہا!اس کے باوجوداللہ انہیں توبہ کرنے نیز تمام بداعمالیو ں کو چھوڑکر اسلام اور ہدایت کی طرف آنے کی دعوت دے رہا ہے۔ (ابن کثیر:۳؍۲۹۹)\n(إنه كان غفورًا رحيمًا)آیت کو اس جملہ پر کیوں ختم کیا گیا؟\nقُلۡ أَنزَلَهُ ٱلَّذِي يَعۡلَمُ ٱلسِّرَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ غَفُورٗا رَّحِيمٗا ٦\nاگر یہ کہا جائے کہ (إِنَّهُ كَانَ غَفورًا رَحيمًا) اس جملہ کی اپنے سے پہلے والے جملہ سے کیا مناسبت ہے تو اس کا جواب یہ ہے کہ: اللہ نے جب پہلے کفار کے اقوال کو ذکر کردیا تو اس کے بعد یہ بتانے کے لئے اس کا ذکر کیا کہ وہ بخشنے والا مہربان ہے،اس طور پر کہ انہیں فوری طور پر سزا نہیں دیا بلکہ انہیں مہلت دی کہ وہ اسلام لے آئیں تو ان کی توبہ قبول فرماکر انہیں معاف کردیگا۔ (ابن جُزی: ۲؍۱۰۳)\nکافروں نے نبی صلی اللہ علیہ وسلم کو جھٹلایا اس جملہ (إِنَّهُ كَانَ غَفورًا رَحيمًا) سے اس کا کیا تعلق ہے؟\nوَقَالُواْ مَالِ هَٰذَا ٱلرَّسُولِ يَأۡكُلُ ٱلطَّعَامَ وَيَمۡشِي فِي ٱلۡأَسۡوَاقِ\nاس آیت سے یہ استدلال کیا گیا ہے کہ علماء اور دیندار صالح لوگ بازار میں جاسکتے ہیں،گرچہ کچھ لوگوں نے مکروہ کہا ہے۔ (الوسی: ۹؍۴۲۷)\nداعی الی اللہ کے لئے سب سے زیادہ معاون چیزوں میں سے تواضع اور لوگوں کے ساتھ میل جول ہے۔ اس آیت سے ہمیں اس کا پتہ کیسے چلا؟\nوَقَالُواْ مَالِ هَٰذَا ٱلرَّسُولِ يَأۡكُلُ ٱلطَّعَامَ وَيَمۡشِي فِي ٱلۡأَسۡوَاقِ\n(هَذا الرّسولِ) “رسول” سے ان کی مراد رسول اللہ صلی اللہ علیہ وسلم ہیں۔(يَأكُلُ الطَّعامَ) یعنی: جیسے ہم کھاتے ہیں وہ بھی کھاتا ہے (وَيَمشِي فِي الأسواقِ)یعنی: معاش اور روزی کی تلاش میں جیسے ہم چلتے پھرتے ہیں وہ بھی بازاروں میں چلتا پھرتا ہے چنانچہ وہ نبوت پاکر ہم سے ممتاز نہیں بن سکتا۔ اور کفار آپ صلی اللہ علیہ وسلم سے یہ بھی کہتے تھے: آپ نہ تو فرشتے ہیں نہ بادشاہ کیونکہ آپ کھانا کھاتے ہیں جبکہ فرشتے نہیں کھاتے اور آپ بادشاہ نہیں ہیں کیونکہ بادشاہ بازاروں میں خرید وفروخت نہیں کرتے جبکہ آپ کرتے ہیں۔ ان کی یہ ساری باتیں فاسد ہیں کیونکہ آپ انسان ہونے کے ناطے کھانا کھاتے تھے اور تواضع وانکساری کے ناطے بازاروں میں چلتے پھرتے تھے اور یہ ایک انسان کی صفت ہے اور یہ ساری چیزیں نبوت کے منافی بالکل نہیں ہیں۔(البغوی: ۳؍۳۲۲)\nداعی کی سچائی کی علامات میں سے تواضع وانکساری اور زندگی کے تمام تصرفات میں واقعیت پسندی ہے۔آیت کے ذریعہ اس کی وضاحت کریں.\nبَلۡ كَذَّبُواْ بِٱلسَّاعَةِۖ\nیعنی یہ لوگ اس طرح کی باتیں سرکشی اور جھٹلانے کی وجہ سے کرتے ہیں۔وہ بصیرت کی بنیاد پر یا ہدایت پانے کے لئے یہ سب طلب نہیں کررہے ہیں بلکہ قیامت کو جھٹلانے کی وجہ سے یہ ساری باتیں کہہ رہے ہیں۔ (ابن کثیر: ؍۳۰۰)\nکفار ومنافقین کے بہت سارے مواقف اور باتوں کی وجہ کیا ہوتی ہے؟\nwords\nنُشُورًاموت كے بعد دوباره اٹھنا.\nإِفكٌ افتَرَاهُجھوٹ جو اپني طرف سے گھڑليا.\nوَزُورًابهت برا جھوٹ.\nسَعِيرًاگرم آگ جو انهيں پگھلا دے."],[361,"§الفرقان\ndeeds\nاس بات سے اللہ کی پناہ اور مغفرت مانگتے رہئے کہ آپ کسی کے گمراہ ہونے یا بہکنے کا سبب بن جائیں۔ اگر ایسا ہوا تو آپ سے اس کے بارے میں بھی پوچھا جائیگا.\nاللہ تعالیٰ سے ہمیشگی کی جنتیں مانگئے اور یہ کہ وہ آپ کو اپنے متقی بندوں میں شامل کرلے.\nیہ دعا مانگئے: “اَللّٰهُمَّ يَا مُقَلِّبَ الْقُلُوْبِ! ثَبِّتْ قَلْبِىْ عَلٰى دِيْنِكَ”۔اے دلوں کو پھیرنے والے!میرے دل کو اپنے دین پر ثابت رکھ.\nguid\nتقوی کی فضیلت ملاحظہ کیجئے! جو بھی ایمان لائے او ر تقویٰ اختیار کرے‘ وہ بلند درجات کا حقدار بن گیا.\nآہ!وہ کتنا خطرناک موقف ہوگا! جب معبود وں سے ان کے عبادت گزاروں کے بارے میں اور مظلوموں سے ان پر ظلم کرنے والوں کے بارے میں پوچھا جائیگا.\nجو انسان اپنے رب سے غافل ہو اس کی عمر دراز ہونا او ر رزق میں کشادگی ہونا اس کے لئے خطرے کی گھنٹی ہے.\nrefl\nإِذَا رَأَتۡهُم مِّن مَّكَانِۢ بَعِيدٖ سَمِعُواْ لَهَا تَغَيُّظٗا وَزَفِيرٗا ١٢\nجہنم اپنے خالق کے غضب کی وجہ سے ان پر غضبناک ہوجائیگی اور ان کے کفر اور شر کی زیادتی کی وجہ سے کہ اس کے شعلے میں تیزی آجائے گی۔ (السعدی؍۵۷۹)\nجہنم جہنمیوں پر اس قدر غضبناک کیوں ہوگی؟\nوَإِذَآ أُلۡقُواْ مِنۡهَا مَكَانٗا ضَيِّقٗا مُّقَرَّنِينَ\nانہیں ایسی جگہ رکھاجائیگا جو بہت ہی تنگ ہوگی،وہاں بہت بھیڑہوگی او ر انہیں زنجیروں او ر بیڑیوں میں جکڑکر رکھاجائیگا۔ (السعدی؍۵۷۹)\nآیت میں کافروں کو عذاب دینے کی مختلف شکلیں بتائی گئی ہیں۔اس کی وضاحت کیجئے.\nوَيَوۡمَ يَحۡشُرُهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمۡ أَضۡلَلۡتُمۡ عِبَادِي هَٰٓؤُلَآءِ أَمۡ هُمۡ ضَلُّواْ ٱلسَّبِيلَ ١٧\nاگر یہ اعتراض کیا جائے کہ وہ بت جن کی پوجا کی جاتی تھی وہ میدان محشر میں جمع ہوکر کیسے باتیں کریں گے حالانکہ وہ جمادات میں سے ہیں؟ تو اس کا جواب یہی ہے کہ قیامت کے دن اللہ تعالیٰ جس طرح ہاتھوں اور پیروں سے بلوائیگا اسی طرح انہیں بھی بولنے کی قوت دے گا۔ (القرطبی: ۱۵؍۳۷۸)\nبت قیامت کے دن کیسے بات کریں گے حالانکہ وہ جمادات ہیں؟\nوَيَوۡمَ يَحۡشُرُهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمۡ أَضۡلَلۡتُمۡ عِبَادِي هَٰٓؤُلَآءِ أَمۡ هُمۡ ضَلُّواْ ٱلسَّبِيلَ ١٧\nمطلب یہ ہے کہ قیامت کے دن اللہ تعالیٰ ان لوگوں سے فرمائیگا جن کی عبادت کی جاتی تھی: (أأنتم أضللتم عبادي هؤلاء أم هم ضلوا السبيل) یعنی: کیا میرے ان بندوں کو تم نے گمراہ کررکھا تھا یا یہ خود اپنے اختیار اور مرضی سے گمراہ ہوئے تھے، تم نے انہیں گمراہ نہیں کیا تھا؟اسی مفہوم کی وضاحت کے لئے: “ هُمْ” کا لفظ لایا تاکہ گمراہی کی نسبت ان کی طرف متحقق ہوجائے سب کچھ جانتے ہوئے اللہ تعالیٰ ان سے یہ سوال کریگاتاکہ ان کافروں کو ڈانٹ پلائے جنہوں نے اُن کی عبادت کی تھی۔ (ابن جزی: ۲؍۱۰۴)\nمعبودان باطلہ سے سوال کرنا دراصل کافروں کو ڈانٹ پلانا ہے۔ اس کی وضاحت کیجئے.\nوَلَٰكِن مَّتَّعۡتَهُمۡ وَءَابَآءَهُمۡ حَتَّىٰ نَسُواْ ٱلذِّكۡرَ وَكَانُواْ قَوۡمَۢا بُورٗا ١٨\nیعنی:دنیا میں صحت وتندرستی،مالداری اور رسولوں کی وفات کے بعد لمبی عمر دے کر انہیں عیش وآرام دیا (حتى نسوا الذكر) یہاں تک کہ انہوں نے تیرا ذکر چھوڑدیا اور تکبر وجہالت میں تیرے ساتھ شرک کربیٹھے۔ (القرطبی: ۱۵؍۳۷۹)\nدنیا کی زیب وزینت میں مست ہونے اور لہوولعب میں مشغول ہوجانے کی بھیانک خطرناکی کی وضاحت کیجئے.\nقَالُواْ سُبۡحَٰنَكَ مَا كَانَ يَنۢبَغِي لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنۡ أَوۡلِيَآءَ وَلَٰكِن مَّتَّعۡتَهُمۡ وَءَابَآءَهُمۡ حَتَّىٰ نَسُواْ ٱلذِّكۡرَ وَكَانُواْ قَوۡمَۢا بُورٗا ١٨\n(سُبحانَكَ) یعنی: انہوں نے اللہ کو اس بات سے پاک سمجھا کہ اس کے ساتھ دوسرے معبود ہوں گے۔(مَا كانَ يَنبَغِي لَنا أَن نَتَّخِذَ مِن دُونِكَ مِن أَولِياءَ) یعنی: ہمارے لئے بالکل یہ مناسب نہیں ہے کہ تیرے دشمنوں کے ساتھ ہم دوستی کریں بلکہ انہیں چھوڑتے ہیں تو ہی ہمارا ساتھی اور دوست ہے۔ اور یہ بھی کہا گیا ہے کہ: ہمارے لئے مناسب نہیں ہے کہ ہم انہیں اپنی عبادت کرنے کا حکم دیں جبکہ ہم تیری عبادت کررہے ہیں۔ (البغوی: ۳؍۳۲۶)\nآیت کی روشنی میں اس بات کی وضاحت کیجئے کہ اللہ کے اولیاء اُن جاہلوں سے کیسے براء ت کا اظہار کریں گے جو اُن کی قبروں پر غلط اعمال انجام دیتے ہیں؟\nوَجَعَلۡنَا بَعۡضَكُمۡ لِبَعۡضٖ فِتۡنَةً أَتَصۡبِرُونَۗ وَكَانَ رَبُّكَ بَصِيرٗا ٢٠\n(وجعلنا بعضكم لبعض فتنة) یعنی مصیبت،فتنہ۔ چنانچہ مالدارفتنہ ہے فقیر کے لئے۔کیونکہ فقیر کہتا ہے کہ کیا ہوا میں اس جیسا نہ ہوسکا۔ اور تندرست مصیبت و فتنہ ہے ایک مریض کے لئے اوربلند مرتبہ شخص مصیبت وفتنہ ہے ایک کم مرتبہ شخص کے لئے۔ اور ابن عباس رضی اللہ عنہما نے فرمایا:یعنی میں نے تم میں سے بعض کو بعض کے لئے فتنہ بنادیا تاکہ ان سے سنی ہوئی باتوں پر صبر کرسکو۔\nلوگ آپس میں ایک دوسرے کے لئے فتنہ ومصیبت کس طرح ہیں؟\nwords\nوَزَفِيرًاغصه كي وجه سے بهت سخت آواز.\nمُقَرَّنِينَهاتھ بيڑيوں كي وجه سے گردن سے ملے هوئے.\nثُبُورًاهلاكت.\nبُورًاهلاك هونے والے.\nصَرفًاعذاب كو ختم كرنا.\nفِتنَةًآزمائش / امتحان."],[362,"§الفرقان\ndeeds\nاللہ سے دعا مانگئے کہ آپ کے نیک اعمال قبول فرمائے.\nاگر آپ کا کوئی برا دوست ہو تواس سے پہلے کہ آپ کو اس کی دوستی پر شرمندگی اور افسوس سے انگلیاں چبانی پڑجائیں اسے چھوڑدیجئے۔ اس کی جگہ نیک دوست ڈھونڈھئے اور اللہ سے دعا کیجئے کہ آپ کو اچھا دوست میسر کردے.\nروزانہ تلاوت کے لئے قرآن کا ایک حصہ مخصوص کرلیجئے.\nguid\nاعمال برباد کردینے والی چیزوں جیسے شرک،ریاکاری،احسان جتانےاور بندوں کو تکلیف دینے سے بچئے.\nاللہ نے مجرموں میں سے ہر نبی کے کچھ دشمن بنائے ہیں۔ اگرآپ دیکھیں کہ کوئی آپ سے دشمنی کررہا ہے تو پریشان نہ ہوں او ر نہ غم کریں کیونکہ یہ تو انبیاء کرام علیہم السلام کا راستہ ہے.\nاللہ کی کتاب (قرآن مجید) مومن کو حق پر ثابت قدم رکھتی ہے چاہے جتنے بھی فتنے ہوں اورکیسے ہی سخت کیوں نہ ہوں.\nrefl\nوَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا ٢٣\nعبداللہ بن مبارک رحمہ اللہ نے فرمایا: یہ وہ اعمال ہونگے جو غیر اللہ کی خاطر انجام دئیے گئے ہونگے۔ مجاہد رحمہ اللہ نے فرمایا: یہ وہ اعمال ہونگے جو قابل قبول نہیں ہونگے۔\nوہ عمل جس سے اللہ تعالیٰ کی خوشنودی مقصود نہ ہو‘اس کی خطرناکی بیان کیجئے.\nٱلۡمُلۡكُ يَوۡمَئِذٍ ٱلۡحَقُّ لِلرَّحۡمَٰنِۚ\nاور جس چیز سے دل کو راحت،نفس کو اطمینان اور انشراح ِصدر حاصل ہوتا ہے وہ یہ کہ اللہ تعالیٰ نے قیامت کے روز اقتدار کی اضافت اپنے اسم مبارک (للرحمن) کی طرف کی ہے جس کی رحمت ہر چیز پر سایہ فگن ہے اور ہر ذی روح کے لئے عام ہے۔ یہ کمزور آدمی اس لئے پیدا کیا گیا ہے اور اسے عزت وتکریم اس لئے عطاکی گئی ہے تاکہ اللہ تعالیٰ اس پر اپنی نعمت کا اتمام کرے اور اسے اپنی رحمت سے ڈھانپ لے۔لوگ تذلّل،خضوع اور انکساری کی حالت میں اللہ تعالیٰ کے حضور حاضر ہوکر انتظار کریں گے کہ وہ ان کے حق میں کیا حکم جاری کرتا ہے اور انہیں کن چیزوں سے دوچار کرتا ہے حالانکہ اللہ تعالیٰ اپنے بندوں پر خود بندوں کی اپنی ذات پر رحم کرنےاور والدین کے اپنے بچوں پر رحم کرنے سے زیادہ رحم کرتا ہے، لہٰذاآپ کا کیا خیال ہے وہ اپنے بندوں کے ساتھ کیسا سلوک کریگا؟(سعدی: ۵۸۲)\nاللہ تعالیٰ نے قیامت کے روز اقتدار کی اضافت اپنے نام (للرحمن) کی طرف کی ہے۔اس سے کیا معلوم ہوتا ہے؟\nوَيَوۡمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيۡهِ يَقُولُ يَٰلَيۡتَنِي ٱتَّخَذۡتُ مَعَ ٱلرَّسُولِ سَبِيلٗا ٢٧\nجو اللہ کو ناراض کرکے لوگوں کو خوش کرےوہ جان لے کہ لوگ اسے اللہ کے عذاب سے ذرہ برابر بھی نہیں بچا پائیں گے۔ایسا آدمی اس ظالم کی طرح ہے جو اپنا ہاتھ کاٹتے ہوئے (شرمندہ ہوکر کہے گا:(يا ليتني اتخذت مع الرسول سبيلًا * يا ويلتى ليتني لم اتخذ فلانًا خليلًا)کاش! میں نے رسول کا راستہ اپنایا ہوتا، ہائے میری تباہی! کاش! میں نے فلاں کو اپنا دوست نہ بنایا ہوتا۔(ابن تیمیہ: ۵؍۱۲)\nجو اللہ کو ناراض کرکے لوگوں کو خوش کرے وہ جان لے کہ لوگ اسے اللہ کے عذاب سے ذرہ برابر بھی نہیں بچا پائیں گے۔اس کی دلیل پیش کیجئے.\nيَٰوَيۡلَتَىٰ لَيۡتَنِي لَمۡ أَتَّخِذۡ فُلَانًا خَلِيلٗا ٢٨ لَّقَدۡ أَضَلَّنِي عَنِ ٱلذِّكۡرِ بَعۡدَ إِذۡ جَآءَنِيۗ وَكَانَ ٱلشَّيۡطَٰنُ لِلۡإِنسَٰنِ خَذُولٗا ٢٩\nآیت میں اس بات کی طرف اشارہ ہے کہ خُلّت(خالص دوستی)کی شان یہ ہے کہ خلیل(محبوب دوست)پر پورا پورا بھروسہ کیا جائے اور اس کے مشورے کو نصیحت پر محمول کیا جائے۔لہذا کسی کے لئے یہ مناسب نہیں کہ وہ اپنی دوستی کا استعمال کرے مگر ایسی جگہ جہاں شک وشبہ اور غلط فہمیوں سے بچنے کا یقین ہو۔(ابن عاشور: ۱۹؍۱۴)\nآیت کی روشنی میں دوستوں کے درمیان نصیحت کی اہمیت واضح کریں.\nلَّقَدۡ أَضَلَّنِي عَنِ ٱلذِّكۡرِ بَعۡدَ إِذۡ جَآءَنِيۗ وَكَانَ ٱلشَّيۡطَٰنُ لِلۡإِنسَٰنِ خَذُولٗا ٢٩\nیعنی: اللہ کی قسم! اس نے قرآن کے راستہ سے مجھے بھٹکادیا حقیقت میں جس کے علاوہ کوئی ذکر نہیں ہے اور اس سے مجھے پھیردیا۔ (البقاعی: ۱۳؍۳۷۵)\nبرے دوستوں کی کیا نشانیاں ہیں؟\nوَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا مِّنَ ٱلۡمُجۡرِمِينَۗ وَكَفَىٰ بِرَبِّكَ هَادِيٗا وَنَصِيرٗا ٣١\nاللہ تعالیٰ اپنے نبی محمد صلی اللہ علیہ وسلم سے فرمارہا ہے: اے محمد! جس طرح ہم نے آپ کی قوم مشرکین میں سے آپ کے دشمن بنائے ہیں اسی طرح آپ سے پہلے بھی ہم نے تمام نبیوں کی قوم کے مشرکین میں سے ان کے دشمن بنائے تھے۔ بنابریں آپ کو نبیوں میں اس تعلق سے کوئی خصوصیت حاصل نہیں ہے۔لہذا ان کی تکلیفوں پرویسا ہی صبر کیجئے جیسا آپ سے پہلے اولواالعزم رسولوں نے صبر کیا۔ (طبری: ۱۹؍۲۶۵)\nآزمائش سچے داعی کی نشانیوں میں سے ہے۔آیت کی روشنی میں اس کی وضاحت کیجئے.\nوَقَالَ ٱلَّذِينَ كَفَرُواْ لَوۡلَا نُزِّلَ عَلَيۡهِ ٱلۡقُرۡءَانُ جُمۡلَةٗ وَٰحِدَةٗۚ كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَۖ وَرَتَّلۡنَٰهُ تَرۡتِيلٗا ٣٢\n(كذلك لنثبت به فؤادك) یہ کافروں کے اعتراض کا جواب ہے جس کی مختصر تفصیل یہ ہے کہ ہم نے قرآن کو وقفے وقفے سے اس لئے اتارا ہے تاکہ ہم محمد صلی اللہ علیہ وسلم کا دل مضبوط رکھ سکیں۔ نیز اس کی ایک حکمت یہ بھی ہے کہ قرآن الگ الگ اسباب کی بناپر نازل ہوا ہے جس کا تقاضہ یہ ہے کہ جب کوئی واقعہ پیش آیا اسی کے مطابق قرآن نازل ہوا۔اور ایک فائدہ یہ ہے کہ اس میں ناسخ ومنسوخ بھی ہے اور یکبارگی قرآن کے نزول میں اس کا بیان ممکن نہیں ہے۔(ورتلناه ترتيلا) یعنی ہم نے اسے بکھیرکروقتاً فوقتاً اتاراہے چنانچہ یہ بیس سالوں کی طویل مدت میں نازل ہوا ہے۔ (ابن جزی: ۲؍ ۱۰۷)\nقرآن تھوڑا تھوڑا کرکے نازل ہونے کے بعض فوائد کا ذکر کریں.\nwords\nلاَ يَرجُونَ لِقَاءَنَاوه آخرت پر ايمان نهيں ركھتے.\nوَعَتَواسركشي ميں حدسے تجاوز كر گئے.\nهَبَاءًغبار/ سورج كي روشني ميں نظر آنے والا هلكا غبار.\nمَقِيلًاآرام ده جگه.\nبِالغَمَامِباريك سفيد بادل."],[363,"§الفرقان\ndeeds\nیہ دعا مانگئے: “اَللّٰهُمَّ أَحْسِنْ عَاقِبَتِيْ فِي الْاُمُوْرِ کُلِّهَا وَأَجِرْنِيْ مِنْ خِزْیِ الدُّنْيَا وَعَذابِ الْآخِرَةِ”۔ اے اللہ! ہر کام میں میرا انجام عمدہ رکھ او ر مجھے دنیا کی رسوائی اور آخرت کے عذاب سے محفوظ رکھ.\nدعوت کے کاموں میں کسی داعی کی مدد کیجئے.\nخواہشات ِنفس کی پیروی سے اللہ کی پناہ مانگئے.\nguid\nجب آپ ظالموں کے برباد یاہلاک ہونے کے مقامات کو دیکھیں تو عبرت حاصل کریں اور وہاں سے غفلت وبے پرواہی کے ساتھ نہ گزریں.\nداعی کو چاہئے کہ مدعو کے حالات اور ماحول کا خیال رکھے چنانچہ ان کے حالات و ظروف کی مناسبت سے دعوت دے.\nمشرکین اپنے باطل پر جمے رہتے ہیں تو آپ ان کی بہ نسبت اورزیادہ شدت سے اپنے دینِ حق پر صبر کے ساتھ جمے رہئے .\nrefl\nوَلَا يَأۡتُونَكَ بِمَثَلٍ إِلَّا جِئۡنَٰكَ بِٱلۡحَقِّ وَأَحۡسَنَ تَفۡسِيرًا ٣٣\nیہ آیت کریمہ دلالت کرتی ہے کہ علمی گفتگو کرنے والے محدث،معلّم یا واعظ کے لئے مناسب ہے کہ وہ اپنے رب کی تدبیر کی پیروی کرے یعنی جس طرح اللہ تعالیٰ نے اپنے رسول صلی اللہ علیہ وسلم کے احوال کے مطابق تدبیر فرمائی۔اسی طرح عالم کو چاہئے کہ وہ مخلوق کے معاملہ میں اسی طرح تدبیر کرے جب بھی کوئی ایسا سبب یا موقع پیش آئے تو موقع کی مناسبت سے لوگوں میں آیات ِ قرآنیہ،احادیث نبویہ اورمواعظ بیان کرے۔ (السعدی؍ ۵۸۲)\nآیت کی روشنی میں داعی ومعلم کی حکمت میں سے کچھ کی وضاحت کیجئے.\nٱلَّذِينَ يُحۡشَرُونَ عَلَىٰ وُجُوهِهِمۡ إِلَىٰ جَهَنَّمَ أُوْلَٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ سَبِيلٗا ٣٤\n(الذين يحشرون)یعنی: چہروں کے بل الٹا کرکے انہیں چلایا جائیگا اور زبردستی انہیں اکٹھاکیا جائیگا(على وجوههم) یا گھسیٹتے ہوئے انہیں جہنم کی طرف لےجایا جائے گا (إلى جهنم) گویا وہ دنیا میں کوئی بھی عمل اس طرح انجام دیتے تھے جیسے اس میں ان کے پاس نہ بصیرت ہو اور نہ ہی ان کا کوئی تصرف۔ شیطان انہیں برابر اکساتا رہتا تھا۔ یقینا ًآخرت دنیا کا آئینہ ہوگی،یہاں جو بھی کیا جائیگا وہاں دِکھائی دیگا،بالکل ویسے ہی جیسے دنیا آخرت کی کھیتی ہے۔جو بھی یہاں کیا جائیگا اس کا پھل وہاں ملے گا۔ امام بخاری رحمہ اللہ نے انس رضی اللہ عنہ سے روایت کی ہے کہ ایک شخص نے کہا: اے اللہ کے نبی!ایک کافر قیامت کے دن اپنے چہرے کے بل کیسے اٹھایاجائیگا؟تو آپ صلی اللہ علیہ وسلم نے فرمایا: جو دنیا میں اسے پیروں کے بل چلاتا ہے کیا وہ اس بات پر قادر نہیں ہے کہ اسے قیامت کے دن چہرے کے بل چلائے!انس رضی اللہ عنہ سے روایت کرنے والے تابعی قتادہ رحمہ اللہ فرماتے ہیں:رب کی عزت وجلال کی قسم!بالکل ایسا ممکن ہے۔ (البقاعی: ۱۳؍ ۳۸۲)\nبدلہ عمل کی ہی جنس سے ملتا ہے۔آیت نے اس مفہوم کی طرف کیسے اشارہ کیا ہے؟\nوَقَوۡمَ نُوحٖ لَّمَّا كَذَّبُواْ ٱلرُّسُلَ أَغۡرَقۡنَٰهُمۡ وَجَعَلۡنَٰهُمۡ لِلنَّاسِ ءَايَةٗۖ\n(كذبوا الرسل) قوم ِنوح نے صرف ایک ہی نبی یعنی نوح علیہ السلام کی تکذیب کی تھی لیکن یہاں (الرُّسُلَ) جمع کا صیغہ لا یا گیا ہے کیونکہ ایک نبی کی تکذیب تمام نبیوں کی تکذیب ہے۔ اسی لئے عبارت میں جمع کا صیغہ لایا گیا ہے اور اس میں قوم نوح کے ساتھ سخت کلامی بھی مقصود ہے۔ (ابن عطیہ: ۴؍ ۲۱۰)\nقوم نوح کی جانب تمام نبیو ں کی تکذیب کی نسبت کیوں کی گئی حالانکہ ا ن کی طرف صرف ایک ہی نبی بھیجے گئے تھے؟\nوَقَوۡمَ نُوحٖ لَّمَّا كَذَّبُواْ ٱلرُّسُلَ أَغۡرَقۡنَٰهُمۡ وَجَعَلۡنَٰهُمۡ لِلنَّاسِ ءَايَةٗۖ وَأَعۡتَدۡنَا لِلظَّٰلِمِينَ عَذَابًا أَلِيمٗا ٣٧ وَعَادٗا وَثَمُودَاْ وَأَصۡحَٰبَ ٱلرَّسِّ وَقُرُونَۢا بَيۡنَ ذَٰلِكَ كَثِيرٗا ٣٨ وَكُلّٗا ضَرَبۡنَا لَهُ ٱلۡأَمۡثَٰلَۖ وَكُلّٗا تَبَّرۡنَا تَتۡبِيرٗا ٣٩\nاللہ تعالیٰ نے جن پچھلی قوموں کی طرف رسولوں کو بھیج کر انہیں ہلاک کیا ان کی مثال پیش کرکے یہ بتانا چاہتاہے کہ بغیر حجت قائم کئے اللہ تعالیٰ نے کسی کو ہلاک نہیں کیا ہے’’۔ (ابن تیمیہ: ۵؍۱۴)\nگناہ گار سزا کے مستحق کب ہوتے ہیں؟\nوَلَقَدۡ أَتَوۡاْ عَلَى ٱلۡقَرۡيَةِ ٱلَّتِيٓ أُمۡطِرَتۡ مَطَرَ ٱلسَّوۡءِۚ أَفَلَمۡ يَكُونُواْ يَرَوۡنَهَاۚ بَلۡ كَانُواْ لَا يَرۡجُونَ نُشُورٗا ٤٠ وَإِذَا رَأَوۡكَ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِي بَعَثَ ٱللَّهُ رَسُولًا ٤١\n(ولقد أتوا على القرية) اس میں (أتوا) فعل میں جو ضمیر ہے وہ کفار قریش وغیرہ کی طرف لوٹ رہی ہے۔ بستی سے مراد قوم لوط کی بستی ہے اور بری بارش سے مراد پتھروں والی بارش ہے۔ پھر اللہ تعالیٰ نے کفار قریش سے اس بستی کو دیکھنے کے تعلق سے سوال کیاکیونکہ وہ ان کےاور ملک ِشام کے راستہ میں واقع ہے۔پھر اللہ نے یہ خبر دی کہ اس سے ان کے نصیحت نہ پکڑنے کی وجہ دراصل ان کا حشر کا انکارکرنا ہے۔ (ابن جزی: ۲؍۱۰۸)\nآیت کی روشنی میں بتائیں کہ کفار نشانیوں اور حوادث سے نصیحت نہیں پکڑتے تھے۔اس کی کیا وجہ ہے؟\nأَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيۡهِ وَكِيلًا ٤٣\n(أرأيت من اتخذ إلهه هواه) یعنی جس چیز کو بھی اپنے دل میں اچھا مان لیا وہی اس کا دین اور مذہب ہوگیا جیسا کہ اللہ تعالیٰ نے فرمایا ہے:﴿أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنٗاۖ فَإِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۖ فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَيۡهِمۡ حَسَرَٰتٍ﴾ (سورۂ فاطر: ۸)کیا وہ شخص جس کے لئے اس کے برے اعمال مزین کردئیے گئے ہیں اور وہ انہی کو اچھا سمجھ رہا ہے، یقین مانو کہ اللہ جسے چاہے گمراہ کرتا ہے اور جسے چاہے راہ راست دکھاتا ہے لہٰذا آپ کو ان پر غم کھاکر اپنی جان ہلاکت میں نہ ڈالنی چاہئے! (ابن کثیر: ۶؍۱۱۳)\nخواہشات نفس کی عبادت کیسے ہوتی ہے؟\nأَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيۡهِ وَكِيلًا ٤٣\nیعنی اپنی خواہش اور مرضی کو اطاعت کے لائق بنادیا یوں وہ معبود کی طرح ہوگیا اور خواہش ومرضی ہر فساد کی طرف لے جانے والی ہے کیونکہ نفس برائیوں کی طرف مائل کرنے والا ہے۔ (ابن عطیہ: ۴؍ ۲۱۲)\nکسی بندے کو کب کہا جائیگا کہ وہ اپنی خواہشات کا غلام ہے؟\nwords\nوَأَصحَابَ الرَّسِّاور كنوئيں والے.\nوَقُرُونًاامتيں.\nالأَمثَالَحجتيں.\nتَبَّرنَاهم نے هلاك كرديا.\nمَطَرَ السَّوءِآسمانوں سے پتھر؛ جس نے انهيں هلاك كرديا.\nكَادَ لَيُضِلُّنَاقريب تھا كه هميں بتوں كي عبادت سے پھير ديتا."],[364,"§الفرقان\ndeeds\nسایہ او ر سورج کی نعمتوں پر غورکیجئے اور اس سے حاصل ہونے والے تین فوائد لکھئے.\nاللہ سے دعا کیجئے کہ زمین اور بندوں کو سیراب کرے اورآپ جب بھی پانی پئیں تو اللہ کی رحمت وفضل پر اس کا شکر ادا کریں.\nاپنے کسی رشتہ دار کے ساتھ صلہ رحمی کیجئے چاہے ان کی زیارت کرکے یا ان سے بذریعہ فون رابطہ کرکے.\nguid\nخصوصاً آخرت سے متعلقہ امور میں کافر بالکل جانور کی مانند ہیں بلکہ جانور کافر سے اچھے ہیں.\nاپنی زندگی فطرت کے موافق بنائیے چنانچہ رات میں سوئیے اور دن میں کام کیجئے.\nداعی کے لئے ضروری ہے کہ دعو ت وجہاد میں ہر ممکن کوشش صرف کرے.\nrefl\nأَمۡ تَحۡسَبُ أَنَّ أَكۡثَرَهُمۡ يَسۡمَعُونَ أَوۡ يَعۡقِلُونَۚ إِنۡ هُمۡ إِلَّا كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّ سَبِيلًا ٤٤\nان کی اکثریت عقلی اور سمعی دلیلوں کو سمجھنے سے قاصر ہے۔چند کو چھوڑکر اکثریت کی نفی کی گئی ہے کیونکہ ان کے اکثر گنوار عوام اور مقلدین کی یہی حالت ہے۔ جبکہ ان میں کچھ عقلمند بھی ہیں جو دلیلوں کو سمجھتے ہیں اور کائنات کی نشانیوں سے استدلال بھی کرتے ہیں لیکن ان پر سرداری کی محبت غالب ہے لہذا انہیں یہ گوارا نہیں ہے کہ نبی صلی اللہ علیہ وسلم کے تابع بن کر دیگر قریش کے کمزورلوگ اور ان کے غلاموں عمار وبلال جیسوں کی صف میں کھڑے ہوجائیں۔ (ابن عاشور: ۱۹؍۳۷)\nسمعی اور عقلی دلیلوں کے سمجھنے کی نفی سارے مشرکین سے کیوں نہ کی گئی؟\nأَمۡ تَحۡسَبُ أَنَّ أَكۡثَرَهُمۡ يَسۡمَعُونَ أَوۡ يَعۡقِلُونَۚ إِنۡ هُمۡ إِلَّا كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّ سَبِيلًا ٤٤\nکیونکہ یہ سننے کے بعد بھی اپنی حرکتوں سے باز نہیں آتے ہیں جبکہ جانور باز آجاتے ہیں۔یہ اپنے محسن کا شکریہ ادا نہیں کرتے جبکہ وہی ان کا کارساز ہے۔ برائی کرنےوالوں سے دور نہیں رہتے جبکہ وہی لوگ ان کے دشمن ہیں۔ یہ نہ ثواب کی رغبت رکھتے ہیں اور نہ عذاب سے ڈرتے ہیں کیونکہ ان کی گمراہی کے بلند پہاڑوں جیسے سایوں کے ذریعہ ان کی عقلوں کے روشن سورج کو ہم نے پردے میں ڈال رکھا ہے۔اگر وہ ایمان لے آئیں تو یہ پردے ہٹ جائیں گے اور ایمان کی کرنیں روشن ہوجائیں گی پھر وہ انوکھے و دقیق معانی ومقاصد کو پہچان لیں گے اور ان پر قدرت کے راز ظاہر ہونے لگیں گے﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ يَهۡدِيهِمۡ رَبُّهُم بِإِيمَٰنِهِمۡ﴾ (سورۂ یونس: ۹)بیشک جو ایمان لائے اور نیک اعمال انجام دئیےان کا رب انہیں ان کے ایمان کی وجہ سے ہدایت پر رکھے گا۔ (البقاعی: ۱۳؍۳۹۵)\nکفار جانورو ں سے زیادہ گمراہ کیوں ہیں؟\nإِنۡ هُمۡ إِلَّا كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّ سَبِيلًا ٤٤\nوہ چوپایوں سے زیادہ گمراہ ہیں کیونکہ ان کا چرواہا انہیں جب سیدھے راستہ کی طرف بلاتا ہے تو چلے جاتے ہیں اور وہ اپنی ہلاکت کے راستہ کو پہچان کر اس سے بچ جاتے ہیں نیز انجام کے اعتبار سے یہ جانور ان کافروں سے زیادہ محفوظ ہوتے ہیں۔ (السعدی؍ ۵۸۴)\nجانور کافروں کے مقابلہ میں زیادہ راہ راست پر ہیں۔ اس کی کیاوجہ ہے؟\nأَلَمۡ تَرَ إِلَىٰ رَبِّكَ كَيۡفَ مَدَّ ٱلظِّلَّ وَلَوۡ شَآءَ لَجَعَلَهُۥ سَاكِنٗا ثُمَّ جَعَلۡنَا ٱلشَّمۡسَ عَلَيۡهِ دَلِيلٗا ٤٥\nسائے کو پھیلانا اور اسے سکیڑنا ایک ایسی نعمت ہے جس کے ذریعہ دن میں نماز اور دیگر کاموں کے اوقات کی جانکاری ہوتی ہے،وہیں پر سور ج کی شعاؤں اور سائے کے فوائد سے لوگوں اور زمین کے مختلف خطوں کا باری باری مستفید ہونا بھی ایک بہت بڑی نعمت ہے کیونکہ جو لوگ سورج کی شعاؤں میں رہنے کی وجہ سے گرمی محسوس کررہے تھے اب وہ اس کے سایوں سے ٹھنڈک حاصل کرتے ہیں اور جو لوگ اس کے سایوں میں تھے اب وہ اس کے سکڑ جانے سے فائدہ اٹھاتے ہیں۔ (ابن عاشور: ۱۹؍۴۳)\nسائے کے پھیلنے اور سکڑنے میں اللہ کی عظیم نعمت کی وضاحت کریں.\nوَلَوۡ شِئۡنَا لَبَعَثۡنَا فِي كُلِّ قَرۡيَةٖ نَّذِيرٗا ٥١\nہم نے رسول اللہ صلی اللہ علیہ وسلم کو سب کے لئے ڈرانے والا بناکر بھیجا ہے تاکہ آپ کا مقام بلند ہوجائے۔چنانچہ آپ صلی اللہ علیہ وسلم اپنے اوپر اللہ کی نعمت کا شکریہ ادا کریں۔ (القرطبی: ۱۵؍۴۴۹)\nاللہ کے نبی صلی اللہ علیہ وسلم کو سب کے لئے ڈرانے والا بناکر بھیجاگیا۔اس کی حکمت واضح کریں.\nفَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَجَٰهِدۡهُم بِهِۦ جِهَادٗا كَبِيرٗا ٥٢\nاس آیت سے یہ استدلال کیا جاتا ہے کہ سب سے بڑا جہاد علماء کا جہاد ہے جو دین کے دشمنوں پر دلیلیں پیش کرتے ہیں۔اور قرآن کے ذریعہ جہاد کرنے والے علماء کا مقام اور حصہ سب سے بڑا ہے۔ (الوسی: ۱۰؍۳۳)\nقرآن کے ذریعہ جہاد کیسے ہوگا؟\nوَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُهُمۡ وَلَا يَضُرُّهُمۡۗ وَكَانَ ٱلۡكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرٗا ٥٥\nیہاں نقصان کی نفی، نفع کی نفی کے بعد کی گئی ہے اس بات پر تنبیہ کے لئے تاکہ بتوں کے پجاریوں کو اپنے شرک کے بارے میں کوئی شبہ نہ رہ جائے کیونکہ کسی کی پوجا یا تو نفع کی امید میں کی جاتی ہے یا اس کے نقصان سے بچنے کے لئے اور یہ دونوں چیزیں بتوں میں نہیں پائی جاتی ہیں جیسا کہ مشاہدہ ہے۔ (ابن عاشور: ۱۹)\nہمیں قبروں اور درگاہوں کی پوجا کرنے سے کیوں روکا گیا ہے؟\nwords\nمَرَجَخلط هوگيا/ مل گيا.\nفُرَاتٌبهت ميٹھا.\nأُجَاجٌبهت كھارا.\nبَرزَخًاركاوٹ جو ايك كو دوسرے سے ملنے نه دے.\nوَحِجرًا مَحجُورًاپرده جو ايك كو دوسرے تك نه پهنچنے دے.\nظَهِيرًارب كے خلاف شيطان كا مددگار۔ شرك كرانے والا ؛ گناه پر مددگار."],[365,"§الفرقان\ndeeds\nنبی صلی اللہ علیہ وسلم کی پیروی کیجئے اور آج کسی گناہ گار یا غافل کو دعوت دیجئے اور ڈرانے والی باتوں سے پہلے خوش کن باتوں سے دعوت کا آغاز کیجئے.\nراتوں میں نماز تہجد ادا کیجئے.\nآج کوشش کیجئے کہ آپ کا اپنی ذات یا گھر والوں پرخرچ فضول خرچی اور بخیلی کے درمیان(معتدل) ہو.\nguid\nداعی کو حتی الامکان مدعو کے مال سے بے پرواہ رہنا چاہئے او ران سے اجرت بھی نہیں مانگنی چاہئے۔کیونکہ یہ اللہ کا تقرب حاصل کرنے کا ذریعہ اور داعی کے سچے ہونے کی نشانی ہے.\nاللہ کے علاوہ پر اعتماد نہ کیجئے کیونکہ وہ مرجائیگا اور صرف اللہ پر توکل کیجئے کیونکہ وہ زندہ رہیگا کبھی نہیں مریگا.\nجہاں بھی رہئے اللہ سے شرم کیجئے۔کیونکہ وہ آپ کے تمام گناہوں کی پوری جانکاری رکھتا ہے.\nrefl\nقُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلٗا ٥٧\n(ما أسألكم عليه) یعنی: جنت کی بشارت اور جہنم سے آگاہی کی تبلیغ پر میں کچھ نہیں مانگتا۔(من أجر)یعنی کوئی اجرت، تاکہ تم لوگ اس کی وجہ سے متہم نہ کرو کہ میں اسی لئے دعوت کا کام کرتا ہوں۔یا یہ کہو کہ اس کی طرف کوئی خزانہ کیوں نہیں اتاردیا جاتاکہ وہ بے نیاز ہوجاتا۔گویا نبی صلی اللہ علیہ وسلم کہہ رہے ہیں کہ مال کی توسیع اور اس کی زیادتی و افزائش میں لگ جانااس شخص کے لئے ناپسندیدہ ہے جولوگوں سے مانگتا پھرتا ہے۔اور یہ نبوت سے پہلے بھی میری عادت نہیں تھی تو بعد میں کیسے ہوسکتی ہے؟! میرا مقصد صرف تم لوگوں کو نفع پہنچانا ہے۔ (البقاعی: ۱۳؍۴۱۲)\nان سچے داعیوں کی کیا علامت ہے جو انبیاء کے راستہ پر چلتے ہیں؟\nوَتَوَكَّلۡ عَلَى ٱلۡحَيِّ ٱلَّذِي لَا يَمُوتُ وَسَبِّحۡ بِحَمۡدِهِۦۚ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا ٥٨\nآیت میں اس بات کی جانب اشارہ ہے کہ ایک کامل شخص اللہ کے علاوہ کسی پر بھروسہ نہیں کرسکتا کیونکہ جن پر موت طاری ہوتی ہے ان پر بھروسہ کرنا گرچہ وقتی طور پر فائدہ پہنچاسکتا ہے لیکن یہ دائمی نہیں ہوتا۔ (ابن عاشور: ۱۹؍۵۹)\nبھروسہ اس وقت فائدہ دیگا جب وہ صرف اللہ پر ہو۔اس کی وضاحت کیجئے.\nوَإِذَا قِيلَ لَهُمُ ٱسۡجُدُواْۤ لِلرَّحۡمَٰنِ قَالُواْ وَمَا ٱلرَّحۡمَٰنُ أَنَسۡجُدُ لِمَا تَأۡمُرُنَا وَزَادَهُمۡ نُفُورٗا۩ ٦٠\nجب کافروں نے اللہ تعالیٰ (رحمٰن) کو سجدہ کرنے سے انکارکیا تو اللہ تعالیٰ نے تعجب کے سیاق میں ان کی اس حالت کو بیان کیااور ان کی مخالفت میں سجدہ کرنے کے عمل کو مشروع قرار دیا، لہٰذا عملاً اللہ کے رسول صلی اللہ علیہ وسلم نے ان کی مخالفت میں مبالغہ کرتے ہوئے سجدہ بھی کیا ۔ (ابن عاشور: ۱۹؍۶۳)\nمذکورہ آیت کریمہ پڑھنے کے بعد سجدہ کرنے کی کیا وجہ ہے؟\nوَهُوَ ٱلَّذِي جَعَلَ ٱلَّيۡلَ وَٱلنَّهَارَ خِلۡفَةٗ لِّمَنۡ أَرَادَ أَن يَذَّكَّرَ أَوۡ أَرَادَ شُكُورٗا ٦٢\nبیشک دل شب وروز کی مختلف گھڑیوں میں اپنی کیفیات کے اعتبار سے تبدیلیوں کا سامنا کرتے رہتے ہیں۔انہیں چستی اور سستی، ذکر اور غفلت، تنگی اور کشادگی،توجہ اور اعراض کی کیفیات پیش آتی رہتی ہیں۔اس لئے اللہ تعالیٰ نے شب وروز کو اس طرح پیدافرمایا ہے کہ وہ تسلسل سے باری باری آتے رہتے ہیں تاکہ ایک کے جانے کے بعد دوسرے وقت میں بندوں کو نشاط،ذکر اور شکر کی کیفیت حاصل ہوتی رہے۔ (السعدی؍ ۵۸۶)\nشب وروز کا آنا جانا اللہ تعالیٰ کی شکر گزاری کے لئے کیسے سبب بنتا ہے؟\nوَهُوَ ٱلَّذِي جَعَلَ ٱلَّيۡلَ وَٱلنَّهَارَ خِلۡفَةٗ لِّمَنۡ أَرَادَ أَن يَذَّكَّرَ أَوۡ أَرَادَ شُكُورٗا ٦٢\nعمر بن خطاب،عبداللہ بن عباس اور حسن رضی اللہ عنہم نے کہا ہے کہ جو شخص خیر وبھلائی اور نماز وغیرہ میں سے کچھ بھی اگر دن یارات میں سے کسی ایک میں اسے کرنا بھول گیا ہو تو اس کی تلافی بعد میں آنے والے وقت کے اندر کرے۔(ابن عطیہ: ۴؍۲۱۸)\nشب وروز کے آنے جانے کا اثر بندے کی عبادت پر کیسے پڑتا ہے؟اسے آیت کی روشنی میں واضح کیجئے.\nوَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا\n(هَوْنًا)یہ “هَيِّن” سے مصدر ہے جو سکینت ووقار کے معنی میں ہے اور اس کی تفسیر میں کہاجاتا ہے کہ وہ بندے زمین پر بردباری اور انکساری وخاکساری کے ساتھ چلتے ہیں،چلنے میں میانہ روی اختیار کرتے ہیں۔اور میانہ روی،وقار اور متانت وسنجیدگی نبوی اخلاق میں سے ہیں۔ (القرطبی: ۱۵؍۴۶۶)\nایک مومن زمین پر کیسے چلتاہے اس کا حسن اخلاق واضح کریں؟\nوَإِذَا خَاطَبَهُمُ ٱلۡجَٰهِلُونَ قَالُواْ سَلَٰمٗا ٦٣\nیعنی جب جاہل ان سے ناپسندیدہ باتوں کے ذریعہ خطاب کرتے ہیں تو یہ ان کو بھلی بات اور اچھے خطاب سے جواب دیتے ہیں۔ (طبری: ۱۹؍۲۹۵)\nجاہلوں کو جواب دینے میں کس طرح حکمت والا طریقہ اپنایا جائے؟اسے واضح کریں.\nwords\nاستَوَى عَلىبلند هوا ؛ اپني شان كے مطابق اونچا اور مستوي هوا.\nنُفُورًادوري.\nبُرُوجًابڑے ستارے؛ اور ان كي منازل.\nخِلفَةًايك دوسرے كے پيچھے.\nهَونًاسكينه ؛ وقار اور تواضع كے ساتھ.\nيَقتُرُوااخراجات ميں كمي كريں.\nقَوَامًامتوسط."],[366,"§الفرقان\ndeeds\nدن بھر میں سوبار اللہ سے توبہ واستغفار کیجئے.\nکسی دن اللہ کی خاطر روزہ رکھئے یا کسی محتاج کی مدد کیجئے.\nاللہ سے دعا کیا کیجئے کہ نیک اولاد اور مبارک بیوی کے ذریعہ آپ کی آنکھیں ٹھنڈی کرے او ر ہمیشہ یہ دعا مانگا کیجئے.\nguid\nحوصلہ بڑا رکھئے اور اللہ سے دعا کیجئے کہ آپ کو متقیوں کا پیشوا بنادے.\nاللہ سے اس طرح ڈرئیے کہ اس کا ڈر آپ کے اور شرک و کبیرہ گناہوں کے درمیان آڑ بن جائے۔نیز اپنے دین اور دنیا پر گناہ کے خطرناک نتائج یاد رکھئے.\nاللہ تعالیٰ کی عظیم رحمت وفضل پر غور کیجئے کہ وہ اپنے توبہ کرنے والے بندوں کے گناہوں کو نیکیوں سے بدل دیتا ہے.\nrefl\nوَٱلَّذِينَ لَا يَدۡعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقۡتُلُونَ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّ وَلَا يَزۡنُونَۚ وَمَن يَفۡعَلۡ ذَٰلِكَ يَلۡقَ أَثَامٗا ٦٨\nسب سے بڑے گناہ تین ہیں:کفر،پھر ناحق قتل کرنا،پھر زنا۔جیسا کہ اللہ تعالیٰ نے ترتیب وار ذکر کیا ہے۔صحیح بخاری اور صحیح مسلم میں عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ انہوں نے پوچھا: اے اللہ کے رسول! سب سے بڑا گناہ کون سا ہے؟فرمایا: تم اللہ کے ساتھ کسی کو شریک بناؤ حالانکہ اسی نے تمہیں پیدا کیا ہے۔پھر میں نے پوچھا: اس کے بعد کون سا ہے؟فرمایا: یہ کہ تم اپنے بچے کواپنے ساتھ کھانے کے ڈر سے قتل کرو۔پھر میں نے پوچھا: اس کے بعد کون ساہے؟ فرمایا: اپنے پڑوسی کی بیوی کے ساتھ زنا کرنا۔ اس ترتیب کی ایک معقول وجہ ہے،وہ یہ کہ انسان کے اندر تین قوتیں ہیں:۱۔ عقل کی قوت،۲۔ غصہ کی قوت اور۳۔ شہوت کی قوت۔(ابن تیمیہ: ۵؍۲۱-۲۲)\nشرک،قتل اور زنا جیسے کبیرہ گناہوں کو آیت کریمہ کے اندر مذکورہ ترتیب سے کیوں ذکرکیا گیا؟\nإِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلٗا صَٰلِحٗا فَأُوْلَٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمۡ حَسَنَٰتٖۗ\nگذشتہ کے گناہ خالص توبہ کے ساتھ ہی نیکیوں میں تبدیل ہوجاتے ہیں کیونکہ جب بھی آدمی اپنے گذشتہ گناہوں کو یاد کرتا ہےاس پر شرمندہ ہوتا ہے اور اللہ کی طرف پلٹتا ہے اور استغفار کرتا ہے تو اس اعتبار سے وہ گناہ نیکی میں بدل جاتا ہے۔چنانچہ قیامت کے دن گرچہ وہ اس پر لکھا ہوا ہوگا لیکن اسے کوئی نقصان نہیں پہنچائے گا بلکہ وہ نامہ اعما ل میں نیکی سے بدل جائیگا۔ (ابن کثیر:۳؍ ۳۱۶)\nآیت کی روشنی میں سچی توبہ کی عظیم فضیلت بیان کیجئے.\nوَٱلَّذِينَ لَا يَشۡهَدُونَ ٱلزُّورَ وَإِذَا مَرُّواْ بِٱللَّغۡوِ مَرُّواْ كِرَامٗا ٧٢\n(لا يشهدون الزور) یہ “شہادت” سے ہے گواہی دینے کے معنی میں۔ یعنی وہ جھوٹی گواہی نہیں دیتے ہیں۔ ایک مطلب یہ بھی بتایا گیا ہے کہ وہ جھوٹ اور لہوولعب کی مجلسوں میں نہیں جاتے ہیں چنانچہ اس صورت میں یہ لفظ مشاہدہ اور حضور کے معنی میں ہوگا۔البتہ پہلا معنی زیادہ ظاہر لگ رہا ہے (وإذا مروا باللغو مروا كرامًا)قبیح باتوں کی تمام قسموں کو لغو کہتے ہیں اور(مروا كرامًا) کا مطلب ہے کہ وہ اس مجلس میں جانے سے شرماتے ہیں اور اس سے اعراض کرتے ہیں اور اپنے کو پاک وصاف رکھنے کے لئے لغو میں شریک لوگوں کے ساتھ شریک نہیں ہوتے ہیں۔ (ابن جُزی: ۲؍۱۱۳)\nاگر ایک مسلمان کسی ایسی مجلس سے گذرے جہاں قبیح گفتگو یا معصیت کے کام ہورہے ہوں تو وہ کیا کرے؟\nوَٱلَّذِينَ إِذَا ذُكِّرُواْ بِـَٔايَٰتِ رَبِّهِمۡ لَمۡ يَخِرُّواْ عَلَيۡهَا صُمّٗا وَعُمۡيَانٗا ٧٣\n(لم يخروا عليها صمًّا وعميانًا) یعنی وہ لوگ اللہ کی آیات سے اعراض نہیں کرتے ہیں بلکہ وہ اپنے کانوں اور دلوں کے ساتھ یعنی پوری توجہ سے ان کی طرف متوجہ ہوتے ہیں۔(ابن جُزی: ۲؍ ۱۱۳)\nقرآنی آیات سنتے وقت ایک مسلمان کو کن صفات کا حامل ہونا چاہئے؟\nوَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعۡيُنٖ\nوہ اللہ تعالیٰ کوجامع و کامل دعاؤں سے پکارتے ہیں جس کی وجہ سے ان کی بیویاں اور بچے نیک وصالح بنتے ہیں، اور اس کا لازمی تقاضہ یہ ہے کہ وہ ان کی تعلیم و تربیت اور وعظ و نصیحت میں بھرپور کوشش و محنت کرتے ہیں۔کیونکہ جو کوئی کسی چیز کی خواہش کرتا ہے اور اس بارے میں اللہ تعالیٰ سے دعا کرتا ہے وہ لازمی طور پر اس (کی حصولیابی) کا وسیلہ اور سبب بن جاتا ہے۔ (السعدی: ۵۸۸)\nبیویوں اور اولاد کی اصلاح کی دعاکرنا کس چیز کا تقاضہ کرتا ہے؟\nوَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعۡيُنٖ\nامام قرظی نے کہا:ایک مومن کے لئے سب سے زیادہ سکون اورآنکھوں کی ٹھنڈک اسی میں ہے کہ وہ اپنی بیوی اور اولاد کو اللہ کا فرمانبردار دیکھے۔ (البغوی: ۳؍ ۳۴۷)\nوہ سب سے عظیم چیز کیا ہے جس سے ایک مومن کو آنکھ کی ٹھنڈک ملتی ہے؟\nأُوْلَٰٓئِكَ يُجۡزَوۡنَ ٱلۡغُرۡفَةَ بِمَا صَبَرُواْ وَيُلَقَّوۡنَ فِيهَا تَحِيَّةٗ وَسَلَٰمًا ٧٥ خَٰلِدِينَ فِيهَاۚ حَسُنَتۡ مُسۡتَقَرّٗا وَمُقَامٗا ٧٦\nیہ کل گیارہ خصلتیں ہوئیں: خاکساری وبردباری،تہجد گذاری وخوف الٰہی،فضول خرچی و بخیلی نہ کرنا، شرک سے بچنا، زنا نہ کرنا،ناحق قتل نہ کرنا،توبہ کرنا، جھوٹ نہ بولنا،خطاکار کو معاف کرنا،دعوت حق کو قبول کرنا اور دعا کے ذریعہ اللہ تعالیٰ کے محتاج ہونے کا اظہار کرنا۔(ابن عاشور: ۱۹؍۸۴)\nگذشتہ آیتوں میں وہ کون سی نیک عادتیں ہیں جن کو نیک بندوں کی صفت بتایا گیا ہے؟انہیں شمار کریں اور خود اپنانے کی کوشش کریں.\nwords\nمَتَابًاصحيح رجوع.\nلَم يَخِرُّواغفلت ميں سجده ميں نهيں گرے بلكه اطاعت گزاري جان كر سجده كيا.\nقُرَّةَ أَعيُنٍجس سے آنكھوں كو ٹھنڈ ك محسوس هو/ اس پر هميں خوشي هو/ مانوس هو ں.\nمَا يَعبَأُوه پرواه نهيں كرتا.\nلِزَامًاچپك جانے والا عذاب."],[367,"§الشعراء\ndeeds\nآج کسی وعظ و نصیحت یا علمی محفل میں شرکت کیجئے.\nکسی باغ میں جائیے یا کسی سبزی اور پھل فروش کی دکان پر جائیے اور(سبزیوں و)پھلوں کی الگ الگ قسموں میں اللہ کی عظمت کے مظاہر پر غورکیجئے.\nآپ نے اپنے ساتھیوں یا پڑوسیوں میں کوئی برائی دیکھی ہو تو مناسب طریقہ سے منع کیجئے.\nguid\nقرآن کریم کے معجزہ ہونے کا بیان کیونکہ وہ چندحروف ہی پر مشتمل نازل ہوا ہے جیسے کہ “ط،س،م”وغیرہ مگر کوئی بھی اس جیسا کلام تیارنہیں کرسکا.\nاس بات کا بیان کہ مکہ والوں کے جھٹلانے اور ایمان نہ لانے کی وجہ سے رسول اللہ صلی اللہ علیہ وسلم کو کس قدر دکھ اور غم لاحق تھا.\nاللہ کی آیات کو جھٹلانے او ر ان کے تعلق سے لاپرواہی برتنے پر دھمکی ہے.\nrefl\nوَمَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّنَ ٱلرَّحۡمَٰنِ مُحۡدَثٍ إِلَّا كَانُواْ عَنۡهُ مُعۡرِضِينَ ٥\nان کے اعمال کی قباحت کی شدت اور ان کے گناہوں کی ہولناکی کوبیان کرنے کے لئے رحمت کی صفت کا ذکر ہوا ہے کیونکہ اللہ تبارک وتعالیٰ کی طرف سے مطلق کسی چیز کے آنے پر اس سے اعراض کرنا بہت ہی قبیح عمل ہے اور ایسی چیز سے اعراض جو رحمت کا باعث ہواور خالص لوگوں کی منفعت کے لئے ہو تو وہ اور ہی زیادہ گھناؤنااور قبیح ہے۔ یعنی آیت کا مفہوم یہ ہے کہ اللہ کی طرف سے جب بھی تذکیر و موعظت و نصیحت یا قرآن کی ایسی آیتیں نازل ہوتی ہیں جو اللہ کی رحمت کا باعث ہوتی ہیں اور جو حکمت ومصلحت کے اعتبار سے باربار نازل ہوتی رہتی ہیں تو وہ ہمیشہ ان سے اعراض کرتے ہیں اور اپنے اس برے عمل پر باقی رہتے ہیں۔(الوسی: ۱۰؍۶۱)\nاس موقع پر“رحمٰن” کی صفت کے ساتھ اس کلام کا کیا فائدہ ہے؟\nأَوَ لَمۡ يَرَوۡاْ إِلَى ٱلۡأَرۡضِ كَمۡ أَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجٖ كَرِيمٍ ٧\n(من كل زوج كريم)یعنی پودے کی ہر نفیس قسم سے۔ چنانچہ یہ ہر طرح کے غلے،پھل،دوائیں اور جانوروں کے چارے کو شامل ہے اور اس کی صفت (كَرِيْمٍ) سے اس کے حسن و خوبصورتی اور منفعت و افادیت کو بتایا گیا ہے۔ (ابن جزی: ۲؍ ۱۱۴)\nپودے کو اللہ نے(كَرِيْمٍ) یعنی نفیس کیوں کہا؟\nوَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰٓ\nاللہ تعالیٰ نےپھر موسیٰ علیہ السلام کا قصہ بیان کیا او ر قرآن میں جتنا اس قصے کو بیان کیا ہے اتنا کوئی اور قصہ بیان نہیں ہوا؛ کیونکہ اس میں بہت زیادہ نصیحتیں اور بڑی بڑی حکمتیں موجود ہیں۔اس میں ظالموں اور مومنوں کے ساتھ موسیٰ علیہ السلام کی کہانی کا بیان ہے۔وہ ایک عظیم شریعت لے کر آئے اور وہی صاحب ِتورات ہیں جو قرآن کے بعد سب سے افضل کتاب ہے۔ (السعدی؍۵۸۹)\nقرآن کریم میں موسیٰ علیہ السلام کے قصہ کو دوسروں کے مقابلہ میں زیادہ کیوں دہرایا گیا ہے؟\nوَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئۡتِ ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ١٠ قَوۡمَ فِرۡعَوۡنَۚ أَلَا يَتَّقُونَ ١١\nظلم اپنی تمام قسموں کو عام ہے۔چنانچہ اس میں سے ان کا اپنے نفس پر ظلم کرنا ہے ایسی چیز کی عبادت کرکے جو عبادت کے لائق نہیں۔اور اسی میں سے ان کا لوگوں کے حقوق میں ظلم کرنا ہے کیونکہ انہوں نے بنی اسرائیل کو غلام بنالیا تھا اور ان پر ظلم وجبر کیا تھا۔ (ابن عاشور: ۱۹؍۱۰۴)\nقوم فرعون کے ظلم کی چند قسمیں بیان کیجئے.\nقَالَ رَبِّ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ ١٢ وَيَضِيقُ صَدۡرِي وَلَا يَنطَلِقُ لِسَانِي فَأَرۡسِلۡ إِلَىٰ هَٰرُونَ ١٣ وَلَهُمۡ عَلَيَّ ذَنۢبٞ فَأَخَافُ أَن يَقۡتُلُونِ ١٤\nموسیٰ علیہ السلام کے یہ کچھ عذر تھے جن کے خاتمہ کے لئے اللہ تعالیٰ سے دعا مانگی تھی جیسا کہ سورۂ طہٰ میں فرمایا: ﴿قَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي ٢٥ وَيَسِّرۡ لِيٓ أَمۡرِي ٢٦ وَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي ٢٧ يَفۡقَهُواْ قَوۡلِي ٢٨ وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي ٢٩ هَٰرُونَ أَخِي ٣٠ ٱشۡدُدۡ بِهِۦٓ أَزۡرِي ٣١ وَأَشۡرِكۡهُ فِيٓ أَمۡرِي ٣٢ كَيۡ نُسَبِّحَكَ كَثِيرٗا ٣٣ وَنَذۡكُرَكَ كَثِيرًا ٣٤ إِنَّكَ كُنتَ بِنَا بَصِيرٗا ٣٥ قَالَ قَدۡ أُوتِيتَ سُؤۡلَكَ يَٰمُوسَىٰ﴾ (سورۂ طہ:۲۵-۳۶) (موسیٰ (علیہ السلام) نے کہا اے میرے رب ! میرا سینہ میرے لئے کھول دے۔۰۰۲۵اور میرے کام کو مجھ پر آسان کر دے۔۰۰۲۶اور میری زبان کی گرہ بھی کھول دے۔۰۰۲۷تاکہ لوگ میری بات اچھی طرح سمجھ سکیں۔۰۰۲۸اور میرا وزیر میرے کنبے میں سے کر دے۔۰۰۲۹یعنی میرے بھائی ہارون (علیہ السلام) کو۔۰۰۳۰تو اس سے میری کمر کس دے۔۰۰۳۱اور اسے میرا شریک کار کر دے۔۰۰۳۲تاکہ ہم دونوں بکثرت تیری تسبیح بیان کریں۔۰۰۳۳اور بکثرت تیری یاد کریں ۔۰۰۳۴بیشک تو ہمیں خوب دیکھنے بھالنے والا ہے ۔۰۰۳۵جناب باری تعالىٰ نے فرمایا موسیٰ تیرے تمام سوالات پورے کر دیے گئے ۔۰۰۳۶) (ابن کثیر: ۳؍۳۲۱)\nاس دعا سے موسیٰ علیہ السلام کا مقصد کیا ہے؟\nوَيَضِيقُ صَدۡرِي وَلَا يَنطَلِقُ لِسَانِي فَأَرۡسِلۡ إِلَىٰ هَٰرُونَ ١٣\nآیت میں اس بات کی دلیل ہے کہ جسے اپنے اوپر اعتماد نہ ہو اور اپنی طرف سے کسی کمی وکوتاہی کے خوف میں مبتلا ہو تو اسے چاہئے کہ وہ دوسروں سے مددلے۔اور اس میں اس کے لئے ملامت کی کوئی بات نہیں ہے۔ (القرطبی: ۱۶؍۱۳)\nموسیٰ علیہ السلام نے اللہ تعالیٰ سے ہارون علیہ السلام کو اپنے مشن کی انجام دہی میں مدد کے لئے طلب کیا۔اس سے آپ کو کیا پتہ چلا؟\nوَلَهُمۡ عَلَيَّ ذَنۢبٞ فَأَخَافُ أَن يَقۡتُلُونِ ١٤ قَالَ كَلَّاۖ\nیعنی وہ موسیٰ علیہ السلام کو قتل نہیں کرسکتے۔ اور اسی لئے فرعون موسیٰ علیہ السلام کو قتل نہیں کرسکا حالانکہ اس نے آپ کی سخت ترین مخالفت کی تھی،آپ کی ہر بات کو بے وقوفی ثابت کرنا چاہا تھا اور آپ کو اور آپ کی قوم کو بھٹکانا چاہا تھا۔ (السعدی؍۵۸۹)\nموسیٰ علیہ السلام پر فرعون کو قدرت کیوں نہ حاصل ہوئی؟\nwords\nبَاخِعٌهلاك هونے والا.\nمُحدَثٍتازه دم / ابھي ابھي نازل هونے والا.\nزَوجٍ كَرِيمٍاچھي اور نفع بخش قسم."],[368,"§الشعراء\ndeeds\nیہ دعا مانگئے: “اَللّٰهُمَّ اِنِّيْ أَسْئَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ وَکَلِمَةَ الْحَقِّ فِي الرِّضَا وَالغَضَبِ”۔ اے اللہ! میں تنہائی اور محفل میں تجھ سے ڈرتے رہنے اور رضامندی وناراضی ہر حالت میں حق بات کہنے کا سوال کرتا ہوں.\nکسی کمزور مظلوم کے بارے میں جانئے اور اللہ سے اجر کی امید رکھتے ہوئے اس کا دفاع کیجئے.\nاللہ تعالیٰ کی عظمت کے مظاہر میں سے کسی تین پر غور کیجئے.\nguid\nفطری ڈر اللہ سے ڈرنے کے منافی نہیں ہے.\nمتکبر اور خود کو بڑا سمجھنے والے لوگ جب دلائل سے ہار جاتے ہیں تو ڈرانا،دھمکانااور طاقت استعمال کرنا شروع کردیتے ہیں.\nداعی کو چاہئے کہ مناظرے اور واضح و مضبوط دلائل پیش کرنے کی مشق کرے کیونکہ یہ طریقہ حق کو غالب کرنے میں مفید ہے.\nrefl\nوَتِلۡكَ نِعۡمَةٞ تَمُنُّهَا عَلَيَّ أَنۡ عَبَّدتَّ بَنِيٓ إِسۡرَٰٓءِيلَ ٢٢\nموسیٰ علیہ السلام کہہ رہے ہیں کہ تم نے میری پرورش کی یہ ایسا احسان ہے جو تو مجھے جتا رہا ہے اور بنواسرائیل کو غلام بنانے اور ان کے ساتھ برے سلوک کا اپنا جرم بھول گئے؟یا وہ یہ کہنا چاہتے ہیں کہ میری پرورش کے سبب تم مجھ پر احسان کیسے جتاسکتے ہو حالانکہ تم نے میری پوری قوم کو غلام بنارکھا ہے؟ اور جس کی قوم کو ذلیل کیا جائے وہ ذلیل ہوگیا لہٰذا تمہارا بنی اسرائیل کو غلام بنانا میرے ساتھ تمہارے احسان کو برباد کردیا۔ (البغوی: ۳؍۳۵۶)\nجب فرعون نے احسان جتایا تو اس وقت موسیٰ علیہ السلام نے اس کا جواب کیسے دیا؟\nقَالَ إِنَّ رَسُولَكُمُ ٱلَّذِيٓ أُرۡسِلَ إِلَيۡكُمۡ لَمَجۡنُونٞ ٢٧ قَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُمۡ تَعۡقِلُونَ ٢٨\n(إن كنتم تعقلون)اس میں اس بات کی جانب اشارہ اور تنبیہ ہے کہ جس پاگل پن کی تہمت تم لوگوں نے موسیٰ علیہ السلام پر لگائی ہے وہ دراصل تمہارا مرض ہے۔عقل کے اعتبار سے سب سے زیادہ پاکیزہ اور علم کے اعتبار سے کامل شخص پر تم نے پاگل پن کی تہمت لگائی ہے جب کہ پاگل پن کا شکار تم لوگ ہو کیونکہ تمہاری عقلیں پوری کائنات میں سب سے ظاہر زمین وآسمان اور ان دونوں کے درمیان کی مخلوقات کے خالق کے انکار کے سبب کھوگئی ہیں۔ (السعدی؍۵۹۰)\nموسیٰ علیہ السلام کے جوابی کلام میں فرعون کے موسیٰ علیہ السلام پر پاگل پن کے الزام پر رد ہے۔اسے واضح کیجئے.\nقَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُمۡ تَعۡقِلُونَ ٢٨\nجب موسیٰ علیہ السلام نے نرمی کے ساتھ دعوت دی اور فرعون جواب میں بے ادبی سے پیش آیا تو انہوں نے اس بات پر اپنی دلیل کو ختم کیا: (إن كنتم تعقلون) یعنی تم لوگ اگرعقل ركھتے ہو۔ یعنی تم اس کو اچھی طرح سے جانتے ہوگویا آپ کا یہ کلام نرم ہونے کے ساتھ ساتھ بہت زیادہ چبھنے والابھی ہے اور شرافت وپردہ داری کے باوجود بہت ہی واضح بھی ہے۔ (البقاعی: ۱۴؍۲۷)\nحکمت اس میں ہے کہ مناسب جگہ مناسب بات کی جائے۔اسے آیت کی روشنی میں واضح کریں.\nقَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُمۡ تَعۡقِلُونَ ٢٨\nاگر کوئی اعتراض کرے کہ پہلے (إن كنتم موقنين) پھر آخر میں (إن كنتم تعقلون)کیوں کہا؟ تو اس کا جواب یہ ہے کہ ان کے ایمان لانے کی امید میں موسیٰ علیہ السلام نے نرمی سے کام لیالیکن جب ان کی سرکشی اور مغالطے کو دیکھا تو انہیں اس آخری قول (إن كنتم تعقلون)، کے ذریعہ جھڑکا۔اور اسے فرعون کے قول (إِنَّ رَسُولَكُمُ لَمَجنُونٌ)کے جواب میں پیش کیا۔ (ابن جزی: ۲؍ ۱۱۷)\nموسیٰ علیہ السلام نے فرعون سے پہلے (إن كنتم موقنين) پھر اس کے بعد (إن كنتم تعقلون)کیوں کہا؟\nقَالَ لَئِنِ ٱتَّخَذۡتَ إِلَٰهًا غَيۡرِي لَأَجۡعَلَنَّكَ مِنَ ٱلۡمَسۡجُونِينَ ٢٩\nفرعون بات کرنے میں جب مغلوب ہوگیا اور اس کی دلیلیں ختم ہوگئیں تو وہ اپنے جاہ وجلال اور قوت وسلطنت کے استعمال پر آگیا۔(ابن کثیر: ۳؍ ۳۲۲)\nظالم اس وقت کیا کرتے ہیں جب حجت ودلیل سے عاری ہوجاتے ہیں؟\nفَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ ٣٢\n(مبين) یہ لفظ زیادہ ظاہر ہونے پر دلالت کرتا ہے کیونکہ لفظ کی زیادتی معنی کی زیادتی پر دلالت کرتی ہے۔یعنی یہ بہت ہی واضح اور ظاہراژدھا ہے،اس میں کوئی شبہ نہیں اور نہ یہ خیالی ہے۔ (ابن عاشور: ۱۹؍۱۲۳)\nآیت کریمہ میں اژدھے کو ظاہر اور واضح ہونے کی صفت سے کیوں متصف کیا؟\nقَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَٱبۡعَثۡ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ ٣٦ يَأۡتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٖ ٣٧ فَجُمِعَ ٱلسَّحَرَةُ لِمِيقَٰتِ يَوۡمٖ مَّعۡلُومٖ ٣٨ وَقِيلَ لِلنَّاسِ هَلۡ أَنتُم مُّجۡتَمِعُونَ ٣٩\nیہ سب اللہ تعالیٰ کی طرف سے ہوا تھا کہ اس نے سب کو اس کام پر مسخر کردیا کہ سب ایک جگہ اکٹھاہوجائیں پھر علی الاعلان سب کے سامنے دن کے اجالے میں اس کی نشانیاں، دلائل اور شواہد ظاہر ہوں۔(ابن کثیر: ۳؍۳۲۲)\nجادوگروں کو جمع کرکے فرعون نے موسیٰ علیہ السلام کی حجت ودلیل کو توڑنا چاہا تھا لیکن اس کے مقصد کے الٹاثابت ہوا۔اس کی وضاحت کریں.\nwords\nالضَّآلِّينَجاهل / يه وحي كے نزول سے قبل كي بات هے.\nحُكمًانبوت.\nعَبَّدتَتم نے انهيں غلام بنايا.\nوَنَزَعَ يَدَهُاپنا هاتھ نكالا(اپنے گريبان سے).\nأَرجِهسے پيچھے كردے.\nحَاشِرِينَصبح كے وقت جمع هونے والے لشكر."]])